// ============================================// SPECTRUM AI PRO ENHANCED v3.2.1// Utilities Module - Common Functions (FIXED: Removed export)// ============================================console.log('[DEBUG] sidepanel-bundle.js starting (utils.js)');// UI Utilities/* export */ function showStatus(elementId, message, show = true) { // Removed 'export'  const el = document.getElementById(elementId);  if (!el) {      console.warn("showStatus: Element not found", elementId);      return;  }  const textEl = el.querySelector('span[id$="StatusText"]'); // More specific selector  if (textEl) textEl.textContent = message;  // Use flex as per sidepanel.css for status-message  el.style.display = show ? 'flex' : 'none';  const loaderId = elementId.replace('Status', 'Loader'); // Infer loader ID  const loader = document.getElementById(loaderId);  if (loader?.classList.contains('loader')) {    loader.style.display = show ? 'block' : 'none'; // Loaders use block  }}/* export */ function showError(msg, type = 'error') { // Removed 'export'  console.error(`Spectrum AI (${type.toUpperCase()}): ${msg}`);  const el = document.getElementById('auditStatus'); // Reuse audit status for general errors  if (el) {      el.className = `status-message ${type}`;      // Use the function, not direct DOM manipulation      showStatus('auditStatus', msg, true);      // Hide after a delay      setTimeout(() => {          // Check if the message is still the same before hiding          const textEl = el.querySelector('span[id$="StatusText"]');          if (textEl && textEl.textContent === msg) {              showStatus('auditStatus', '', false);          }      }, 5000);  }}/* export */ function showSuccess(msg) { // Removed 'export'  console.log(`Spectrum AI (Success): ${msg}`);  const el = document.getElementById('auditStatus');  if (el) {      el.className = 'status-message success';      showStatus('auditStatus', msg, true);      setTimeout(() => {           const textEl = el.querySelector('span[id$="StatusText"]');           if (textEl && textEl.textContent === msg) {               showStatus('auditStatus', '', false);           }      }, 3000);  }}// Content Handling/* export */ function escapeHtml(text) { // Removed 'export'  if (typeof text !== 'string') return '';  const div = document.createElement('div');  div.textContent = text;  return div.innerHTML;}// Date & Time Utilities/* export */ function formatDate(dateString) { // Removed 'export'  try {    const date = new Date(dateString);    if (isNaN(date)) return dateString;    const now = new Date();    const diffMs = now - date;    const diffMins = Math.floor(diffMs / 60000);    const diffHours = Math.floor(diffMs / 3600000);    const diffDays = Math.floor(diffMs / 86400000);    if (diffMins < 1) return 'Just now';    if (diffMins < 60) return `${diffMins} minute${diffMins !== 1 ? 's' : ''} ago`;    if (diffHours < 24) return `${diffHours} hour${diffHours !== 1 ? 's' : ''} ago`;    if (diffDays < 7) return `${diffDays} day${diffDays !== 1 ? 's' : ''} ago`;    return date.toLocaleDateString();  } catch (error) {    console.error("Error formatting date:", error);    return dateString;  }}// URL Utilities/* export */ function getHostname(url) { // Removed 'export'  try {    if (!url || typeof url !== 'string' || !url.startsWith('http')) return url || ''; // FIX: Handle non-http URLs better    return new URL(url).hostname.replace(/^www\./, '');  } catch {    return url;  }}// Scoring & Classification/* export */ function getScoreClass(score) { // Removed 'export'  score = Number(score);  if (isNaN(score)) return 'poor';  if (score >= 90) return 'excellent'; // Adjusted threshold  if (score >= 70) return 'good'; // Adjusted threshold  if (score >= 50) return 'fair'; // Adjusted threshold  return 'poor';}// Action & Result Formatting/* export */ function formatActionResult(result) { // Removed 'export'  if (typeof result === 'string') return marked.parse(result); // Use marked from below  if (Array.isArray(result)) {    return '<ul>' + result.map(item => `<li>${escapeHtml(String(item))}</li>`).join('') + '</ul>';  }   try {       return '<pre><code>' + escapeHtml(JSON.stringify(result, null, 2)) + '</code></pre>';   } catch {       return '<pre><code>' + escapeHtml(String(result)) + '</code></pre>';   }}/* export */ function getActionTitle(actionType) { // Removed 'export'  const titles = {    summarize: 'ðŸ“„ Group Summary',    extract: 'ðŸ“Š Extracted Key Data',    contacts: 'ðŸ‘¤ Found Contacts',    analyze: 'ðŸ”¬ Content Analysis',    compare: 'âš–ï¸ Comparison Results',    predict: 'ðŸ”® Trend Predictions'  };  return titles[actionType] || 'Action Results';}// Browser Tab Utilities/* export */ async function getCurrentTab() { // Removed 'export'  try {    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });    return tab;  } catch (error) {    console.error('Get current tab error:', error);    return null;  }}/* export */ async function getTabContent(tabId) { // Removed 'export'  try {    // This sends a message to the service-worker.js    const response = await chrome.runtime.sendMessage({      type: 'get-tab-content',      tabId: tabId    });    if (chrome.runtime.lastError) {        throw new Error(`Connection error: ${chrome.runtime.lastError.message}`);    }    if (response && response.success) {        // console.log(`Content received for tab ${tabId}:`, response.data.title);        return response.data;    } else {        throw new Error(response.error || 'Failed to get tab content (unknown reason).');    }  } catch (error) {    console.error(`Get tab content error for tab ${tabId}:`, error);    // Re-throw a more specific error for the caller    throw new Error(`Could not retrieve content from the tab. ${error.message}`);  }}// Simple markdown parser/* export */ const marked = { // Removed 'export'  parse: (md = "") => {    if (typeof md !== 'string') md = String(md);    return md      .replace(/^### (.*)$/gim, '<h3>$1</h3>')      .replace(/^## (.*)$/gim, '<h2>$1</h2>')      .replace(/^# (.*)$/gim, '<h1>$1</h1>')      .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')      .replace(/\*(.*?)\*/g, '<em>$1</em>')      .replace(/^\s*-\s+(.*)$/gim, '<li>$1</li>') // Basic list item      .replace(/(`)(.*?)(`)/g, '<code>$2</code>')      .replace(/\n/g, '<br>'); // Simple newline conversion    }};// Moved from original utils.js as they depend on AppState from sidepanel-core.js// but need to be defined before they are called. Ensure sidepanel-core.js is bundled after utils.js// but before loadSettings is called in main.jsasync function loadSettings() {  try {    const defaults = {      aiEnabled: true,      darkMode: true,      animations: true,      autoGroup: false,      maxHistory: 100,      screenshotQuality: 0.7    };    const result = await chrome.storage.local.get({ settings: defaults });    // Ensure AppState exists before assigning    if (typeof AppState !== 'undefined') {        AppState.settings = result.settings;        console.log("Settings loaded:", AppState.settings);    } else {        console.error("AppState not defined when loadSettings was called.");        // We will rely on main.js calling this AFTER AppState is defined.    }  } catch (error) {    console.error('Settings load error:', error);     if (typeof AppState !== 'undefined') {        AppState.settings = { aiEnabled: true, darkMode: true, animations: true, autoGroup: false, maxHistory: 100, screenshotQuality: 0.7 }; // Fallback     }  }}async function saveSettings() {  // Ensure AppState exists before trying to save from it  if (typeof AppState === 'undefined' || AppState.settings === null) {      console.error("Cannot save settings: AppState or AppState.settings not available.");      return;  }  try {    await chrome.storage.local.set({ settings: AppState.settings });    console.log("Settings saved:", AppState.settings);  } catch (error) {    console.error('Settings save error:', error);  }}console.log('âœ… Utilities module loaded');/** * AIManager - Production v6.0 * Uses Chrome's built-in Prompt API with Gemini Nano * Updated for Chrome 127+ (No Origin Trial Required) */class AIManager {  constructor() {    this.session = null;    // FIX: More specific availability statuses    this.availability = 'unknown'; // 'unknown', 'unavailable', 'downloadable', 'downloading', 'readily'    this.modelCheckPromise = null; // To prevent multiple checks running concurrently  }  /**   * Check if AI is available using the new API   * @returns {Promise<string>} 'readily', 'after-download', 'downloading', 'unavailable'   */  async checkAvailability() {    // Check if the API structure exists    if (typeof globalThis.ai === 'undefined' || typeof globalThis.ai.languageModel === 'undefined') {      console.warn('âš ï¸ AI API (globalThis.ai.languageModel) not found. Check manifest permission or Chrome version (127+).');      this.availability = 'unavailable'; // FIX: Consistent 'unavailable' status      return 'unavailable';    }    try {      // Call the official availability function      const availability = await globalThis.ai.languageModel.availability();      this.availability = availability;      console.log(`âœ… AI Model availability: ${availability}`);      return availability;    } catch (error) {      console.error('âŒ Error checking AI availability:', error);      this.availability = 'unavailable'; // FIX: Consistent 'unavailable' status      return 'unavailable';    }  }  /**   * Initialize AI Manager and update UI banner   * @returns {Promise<boolean>} true if readily available   */  async initialize() {    // Only run the check once if multiple calls happen quickly    if (!this.modelCheckPromise) {        this.modelCheckPromise = this.checkAvailability();    }    const availability = await this.modelCheckPromise;    this.modelCheckPromise = null; // Reset promise after check completes    const banner = document.getElementById('aiWarningBanner');    const bannerText = document.getElementById('aiWarningText'); // Assuming text span    // FIX: Ensure banner elements exist before trying to modify them    if (!banner || !bannerText) {        console.warn("AI warning banner elements not found in HTML.");        // Attempt to proceed, but banner won't work    }    switch (availability) {      case 'readily':        console.log('âœ… AI Model is readily available.');        if (banner) banner.style.display = 'none'; // Hide banner if ready        return true;      case 'downloadable': // FIX: Correct status name from downloadable        console.log('ðŸ“¥ AI model needs download. Will be triggered on first use.');        if (banner) banner.style.display = 'flex';        if (banner) banner.className = 'status-message warning'; // Ensure correct class        if(bannerText) bannerText.textContent = 'â³ AI Model needs download. Click an AI feature to start.';        // Don't show an error toast here, it's expected        return false; // Not ready yet      case 'downloading': // FIX: Added handling for downloading status        console.log('â³ AI model is downloading...');        if (banner) banner.style.display = 'flex';        if (banner) banner.className = 'status-message warning';        if(bannerText) bannerText.textContent = 'AI Model is downloading...';        // FIX: Show status in relevant sections using utility function        if (typeof showStatus === 'function') {            showStatus('auditorStatus', 'AI Model downloading...', true);            showStatus('organizerStatus', 'AI Model downloading...', true);            showStatus('scribeStatus', 'AI Model downloading...', true);         }        return false; // Not ready yet      case 'unavailable': // FIX: Use 'unavailable' consistently      default:        console.warn('âš ï¸ AI model unavailable on this device.');        if (banner) banner.style.display = 'flex';        if (banner) banner.className = 'status-message error'; // FIX: Ensure error class        if(bannerText) bannerText.textContent = 'âŒ On-Device AI unavailable. Check flags & Chrome version (See Setup page).';        // FIX: Use showError utility function for consistency        if (typeof showError === 'function') {          showError('On-Device AI unavailable. Ensure Chrome 127+, flags enabled, and compatible hardware.', 'warning');        }        return false;    }  }  /**   * Get AI model parameters   * @returns {Promise<Object>} Model parameters   */  async getParams() {    if (typeof globalThis.ai === 'undefined' || typeof globalThis.ai.languageModel === 'undefined') {      throw new Error('AI API not available');    }    try {      const params = await globalThis.ai.languageModel.params();      console.log('ðŸ“Š AI Model Parameters:', params);      return params;    } catch (error) {      console.error('Error getting AI params:', error);      // FIX: Provide reasonable defaults if params() fails      return {        defaultTopK: 3,        maxTopK: 128,        defaultTemperature: 0.7, // Slightly adjusted default        maxTemperature: 2      };    }  }  /**   * Create AI session with download monitoring   * @param {Object} options - Session options { systemPrompt?, temperature?, topK? }   * @returns {Promise<Object>} AI session   */  async createSession(options = {}) {    // Return existing session if readily available    if (this.session && this.availability === 'readily') {      return this.session;    }    // Ensure availability is checked if it hasn't been yet or if session failed previously    const availability = (this.availability === 'unknown' || this.availability === 'unavailable')      ? await this.checkAvailability()      : this.availability;    // FIX: Throw specific error if unavailable after check    if (availability === 'unavailable') {      // Error message is shown by initialize(), just throw      throw new Error('AI model is not available.');    }    // If downloadable or downloading, show status and proceed to trigger creation/download    if (availability === 'downloadable' || availability === 'downloading') {       // FIX: Show status using utility function       if (typeof showStatus === 'function') {          const msg = availability === 'downloading'            ? 'AI Model download in progress...'            : 'Initializing AI Model (downloading may take time)...';          showStatus('auditorStatus', msg, true);          showStatus('organizerStatus', msg, true); // Show on other tabs too          showStatus('scribeStatus', msg, true);       }       console.log("Attempting to trigger AI model download/creation...");    }    try {      // Get model parameters for defaults      const params = await this.getParams();      // Create session, attaching monitor for download progress      this.session = await globalThis.ai.languageModel.create({        // FIX: Allow overriding system prompt via options        systemPrompt: options.systemPrompt ||          'You are a helpful AI assistant specialized in web analysis, tab organization, and workflow documentation. Provide clear, actionable, and concise responses in Markdown format where appropriate.',        // FIX: Use nullish coalescing for temperature and topK        temperature: options.temperature ?? params.defaultTemperature,        topK: options.topK ?? params.defaultTopK,        // Add monitor for download progress        monitor: (m) => {          m.addEventListener('downloadprogress', (e) => {            // FIX: Check if total is known to avoid NaN%            if (!e.total) return;            const progress = Math.round((e.loaded / e.total) * 100);            console.log(`ðŸ“¥ AI Model Download Progress: ${progress}%`);            const msg = `Downloading AI Model: ${progress}%...`;            // Update status on all relevant tabs            if (typeof showStatus === 'function') {                showStatus('auditorStatus', msg, true);                showStatus('organizerStatus', msg, true);                showStatus('scribeStatus', msg, true);            }          });          // FIX: Added listeners for completion and errors           m.addEventListener('downloadcomplete', () => {             console.log('âœ… AI Model Download Complete!');             this.availability = 'readily'; // Update status immediately             if (typeof showSuccess === 'function') showSuccess('AI Model Downloaded!');             if (typeof showStatus === 'function') { // Clear status messages                  showStatus('auditorStatus', '', false);                  showStatus('organizerStatus', '', false);                  showStatus('scribeStatus', '', false);             }             const banner = document.getElementById('aiWarningBanner');             if (banner) banner.style.display = 'none'; // Hide banner on success          });          m.addEventListener('downloaderror', (e) => {              console.error('âŒ AI Model Download Error:', e);              this.availability = 'unavailable'; // Set as unavailable on download error              this.session = null; // Ensure session is nullified               if (typeof showError === 'function') showError('Failed to download AI Model. Check network and storage.', 'error');                if (typeof showStatus === 'function') { // Clear status messages                  showStatus('auditorStatus', '', false);                  showStatus('organizerStatus', '', false);                  showStatus('scribeStatus', '', false);               }          });        }      });      this.availability = 'readily'; // Update status after successful creation      console.log('âœ… AI Session created successfully');      // FIX: Clear status messages only if not already cleared by downloadcomplete       if (typeof showStatus === 'function' && availability !== 'downloading' && availability !== 'downloadable') {        showStatus('auditorStatus', '', false);        showStatus('organizerStatus', '', false);        showStatus('scribeStatus', '', false);      }      // FIX: Hide banner only if not already hidden by downloadcomplete      if (this.availability === 'readily') {         const banner = document.getElementById('aiWarningBanner');         if (banner) banner.style.display = 'none';         // Show success only if it wasn't a download trigger and now ready         if (availability === 'readily' && typeof showSuccess === 'function') {             showSuccess('AI Model Ready!');         }      }      return this.session;    } catch (error) {      console.error('âŒ Failed to create AI session:', error);      this.availability = 'unavailable'; // FIX: Consistent status on error      this.session = null; // Ensure session is null      // Clear loading states      if (typeof showStatus === 'function') {        showStatus('auditorStatus', '', false);        showStatus('organizerStatus', '', false);        showStatus('scribeStatus', '', false);      }      // Show informative error message      if (typeof showError === 'function') {        showError(`AI Session Error: ${error.message}. Please check Chrome flags (see Setup page) and restart Chrome.`, 'error');      }      // Re-throw the error with a more user-friendly message      throw new Error(`Could not create AI session: ${error.message}. Check flags & restart.`);    }  }   /**   * Send prompt and get complete response   * @param {string} message - User prompt   * @param {Object} options - Prompt options { context?: string, signal?: AbortSignal, sessionOptions?: object }   * @returns {Promise<string>} AI response   */   async prompt(message, options = {}) {    // FIX: Pass sessionOptions to createSession if provided    const session = await this.createSession(options.sessionOptions);    const context = options.context || ''; // Get context from options    try {      // FIX: Construct prompt array (allow context via sessionOptions or direct option)      const prompts = [];      // If a system prompt was used for session creation, don't add another here unless explicitly different context is needed      // if (context && (!options.sessionOptions || !options.sessionOptions.systemPrompt)) {      if (context) { // Simpler: always add context if provided as an option here        prompts.push({ role: 'system', content: context });      }      prompts.push({ role: 'user', content: message });      const response = await session.prompt(prompts, { // Pass prompt array        signal: options.signal      });      console.log("âœ… AI Prompt Response:", response);      return response || 'AI did not generate a response.'; // Handle empty response    } catch (error) {      if (error.name === 'AbortError') { // Handle user cancellation        console.log('âš ï¸ AI Prompt aborted by user');        throw error;      }      console.error('âŒ AI Prompt error:', error);      if (typeof showError === 'function') {        showError(`AI Request Failed: ${error.message}`, 'error');      }      throw error; // Re-throw for specific handling    }  }  /**   * Stream prompt with real-time chunks   * @param {string} message - User prompt   * @param {string} [context=''] - Optional system context for this prompt   * @param {Function} [onChunk=null] - Callback function for each received chunk   * @param {Object} [options={}] - Additional options { signal?: AbortSignal, sessionOptions?: object }   * @returns {Promise<string>} Complete final response   */  async streamPrompt(message, context = '', onChunk = null, options = {}) {    const session = await this.createSession(options.sessionOptions); // Ensures session exists    try {      // FIX: Construct prompt array similarly to prompt()      const prompts = [];      if (context) {        prompts.push({ role: 'system', content: context });      }      prompts.push({ role: 'user', content: message });      const stream = await session.promptStreaming(prompts, { // FIX: Pass prompt array        signal: options.signal      });      let fullResponse = '';      for await (const chunk of stream) {        fullResponse = chunk; // In Chrome 127+, each chunk IS the cumulative response so far        if (onChunk) {             // FIX: Wrap onChunk call in try/catch to prevent its errors from stopping stream             try { onChunk(chunk); } catch (chunkError) { console.error("Error in onChunk callback:", chunkError); }        }      }      console.log('âœ… AI Streaming completed. Final response length:', fullResponse.length);      return fullResponse;    } catch (error) {      if (error.name === 'AbortError') { // Handle user cancellation        console.log('âš ï¸ AI Stream aborted by user');        throw error;      }      console.error('âŒ AI Streaming error:', error);      if (typeof showError === 'function') {        showError(`AI Streaming Failed: ${error.message}`, 'error');      }      throw error; // Re-throw    }  }  /**   * Clone current session (preserves system prompt, resets context)   * @returns {Promise<Object>} Cloned session   */  async cloneSession() {    // FIX: Ensure session exists before trying to clone    const session = await this.createSession();    if (!session) { // createSession throws if unavailable, but double-check      throw new Error('Cannot clone: AI session is not available.');    }    try {      const cloned = await session.clone();      console.log('âœ… Session cloned');      return cloned;    } catch (error) {      console.error('âŒ Error cloning session:', error);      throw error;    }  }  /**   * Get current session usage (Note: Chrome 127+ API doesn't expose usage yet)   * @returns {Object} Placeholder usage stats   */  getUsage() {    // The Chrome 127+ API currently doesn't provide inputUsage/inputQuota.    // Return placeholder values.    console.warn("AI session usage information is not available with the current Chrome API.");    return {      inputUsage: 0,      inputQuota: 0,      percentUsed: 0    };  }  /**   * Destroy current session and free resources   */  destroy() {    if (this.session) {      try {        this.session.destroy();        console.log('âœ… AI Session destroyed');      } catch (error) {        console.error('Error destroying AI session:', error);      } finally {        this.session = null;        this.availability = 'unknown'; // Reset status      }    }  }}// Export for global use if needed (e.g., in setup.js)if (typeof window !== 'undefined') {  window.AIManager = AIManager;}// ============================================// SPECTRUM AI PRO ENHANCED v3.2 - MOCK AI// ============================================class MockAIManager {  constructor() {    this.isAvailable = true;  }  async initialize() {    console.log('ðŸ¤– Using Mock AI Manager');    return true;  }  async createSession() {    console.log('ðŸ¤– Mock AI Session Created');    return true;  }  async prompt(message, context = '') {    console.log('ðŸ¤– Mock AI Prompt:', message);    return new Promise(resolve => {      setTimeout(() => {        resolve('This is a mock AI response. The real AI is not available.');      }, 500);    });  }  async streamPrompt(message, context = '', onChunk) {    console.log('ðŸ¤– Mock AI Stream Prompt:', message);    const response = 'This is a mock AI streaming response. The real AI is not available.';    const chunks = response.split(' ');        let fullResponse = '';    for (const chunk of chunks) {      await new Promise(resolve => setTimeout(resolve, 100));      fullResponse += chunk + ' ';      if (onChunk) {        onChunk(fullResponse.trim());      }    }    return fullResponse.trim();  }  destroy() {    console.log('ðŸ¤– Mock AI Destroyed');  }}// ============================================// SPECTRUM AI PRO ENHANCED v3.2.1// Core Module - State, Utilities, UI Init (DEBUGGED)// ============================================console.log('ðŸŒˆ Loading Core Module...');// ===== GLOBAL STATE =====const AppState = {  currentTab: 'auditor',  currentView: 'split',  auditData: null,  auditReport: null,  organizerGroups: null,  selectedGroup: null,  scribeSteps: [],  scribeRecording: false,  settings: null,  charts: {},  auditHistory: [],};// ===== AI SESSION MANAGEMENT =====var aiManager; // Declared globally// ===== UTILITY FUNCTIONS =====// Assume functions like showStatus, showError, etc., are defined above in the bundle// --- UI Initialization Functions ---function initializeUI() {  console.log('[DEBUG] > Running initializeUI...'); // <<< DEBUG LOG  if (!AppState.settings) {      console.warn("Settings not loaded before initializeUI called.");      return;  }  if (AppState.settings.darkMode) {    document.body.classList.add('dark-mode');  } else {    document.body.classList.remove('dark-mode');  }  if (!AppState.settings.animations) {    document.body.classList.add('no-animations');  } else {    document.body.classList.remove('no-animations');  }  console.log('[DEBUG] < Finished initializeUI.'); // <<< DEBUG LOG}function initializeTabNavigation() {  console.log('[DEBUG] > Running initializeTabNavigation...'); // <<< DEBUG LOG  const tabLinks = document.querySelectorAll('.tab-link');  const tabContents = document.querySelectorAll('.tab-content');  if (!tabLinks.length || !tabContents.length) {      console.error("Tab navigation elements not found.");      return;  }  tabLinks.forEach(link => {    link.addEventListener('click', () => {      console.log(`[DEBUG] Tab clicked: ${link.dataset.tab}`); // <<< DEBUG LOG      const targetTabId = link.dataset.tab;      if (!targetTabId || AppState.currentTab === targetTabId) return;      tabLinks.forEach(l => l.classList.remove('active'));      tabContents.forEach(c => { c.classList.remove('active'); c.hidden = true; });      link.classList.add('active');      const targetContent = document.getElementById(targetTabId);      if (targetContent) {        targetContent.classList.add('active');        targetContent.hidden = false;        console.log(`Switched to tab: ${targetTabId}`);      } else {         console.error(`Tab content not found for id: ${targetTabId}`);      }      AppState.currentTab = targetTabId;      updateChatVisibility();    });  });  const initialActiveTab = document.querySelector('.tab-link.active');  const initialTabId = initialActiveTab?.dataset.tab || 'auditor';  tabContents.forEach(c => { c.hidden = (c.id !== initialTabId); });  AppState.currentTab = initialTabId;  updateChatVisibility();  console.log('[DEBUG] < Finished initializeTabNavigation.'); // <<< DEBUG LOG}function initializeViewModes() {  console.log('[DEBUG] > Running initializeViewModes...'); // <<< DEBUG LOG  const viewModeButtons = document.querySelectorAll('.view-mode-btn');  const appContainer = document.querySelector('.app-container');  if (!appContainer) {      console.error("Critical Error: '.app-container' element not found! View modes cannot be applied.");      return;  }   if (!viewModeButtons.length) {      console.error("View mode buttons (.view-mode-btn) not found.");      return;   }  viewModeButtons.forEach(btn => {    btn.addEventListener('click', () => {      console.log(`[DEBUG] View mode clicked: ${btn.dataset.mode}`); // <<< DEBUG LOG      viewModeButtons.forEach(b => b.classList.remove('active'));      btn.classList.add('active');      const mode = btn.dataset.mode;      appContainer.classList.remove('view-split', 'view-results', 'view-chat');      appContainer.classList.add(`view-${mode}`);      AppState.currentView = mode;      console.log(`Switched to view mode: ${mode}`);    });  });   const initialActiveButton = document.querySelector('.view-mode-btn.active');   const initialMode = initialActiveButton?.dataset.mode || 'split';   appContainer.classList.add(`view-${initialMode}`);   AppState.currentView = initialMode;   console.log('[DEBUG] < Finished initializeViewModes.'); // <<< DEBUG LOG}function updateChatVisibility() {  // Only proceed if AppState is fully initialized  if (!AppState || typeof AppState.currentTab === 'undefined') {    console.warn("[DEBUG] updateChatVisibility called before AppState is ready.");    return;  }  const chats = {    auditor: 'auditorChatContainer',    organizer: 'organizerChatContainer',    scribe: 'scribeChatContainer'  };  Object.entries(chats).forEach(([tab, id]) => {    const el = document.getElementById(id);    if (el) {       el.style.display = tab === AppState.currentTab ? 'flex' : 'none';    } else {        // Log warning only if it's the expected active chat        if (tab === AppState.currentTab) {           console.warn(`[DEBUG] Chat container '${id}' not found for active tab '${tab}'.`);        }    }  });}function handleRuntimeMessage(message, sender, sendResponse) {  console.log("Sidepanel received message:", message?.type, "from", sender.tab ? `tab ${sender.tab.id}` : "extension context");  (async () => {    try {      switch (message?.type) {        case 'ping':          console.log("Sidepanel responding to ping");          sendResponse({ ok: true });          break;        case 'scribe-click-captured':          if (typeof handleClickCapture === 'function') {            await handleClickCapture(message.data, message.tabId);          } else {            console.warn("Scribe click received, but handleClickCapture function is not defined.");          }          break;        case 'context-menu-action':        case 'keyboard-command':          const action = message.action || message.command;          console.log(`Sidepanel executing action trigger: ${action}`);          let targetTabId;          switch (action) {            case 'runAudit': case 'run-audit': targetTabId = 'auditor'; break;            case 'organizeTabs': case 'organize-tabs': targetTabId = 'organizer'; break;            case 'startScribe': case 'start-scribe': targetTabId = 'scribe'; break;            case 'openSidepanel':                 if (sendResponse) sendResponse({ received: true, handled: true, action: 'open' });                 return;            default:                 console.warn("Sidepanel received unhandled action trigger via message:", action);                 if (sendResponse) sendResponse({ received: true, handled: false, error: `Unknown action: ${action}` });                 return;          }          const tabLink = document.querySelector(`.tab-link[data-tab="${targetTabId}"]`);          if (tabLink && AppState.currentTab !== targetTabId) {            tabLink.click();            await new Promise(resolve => setTimeout(resolve, 50));          }          try {              switch (action) {                  case 'runAudit': case 'run-audit':                      if (typeof runAudit === 'function') await runAudit(); else throw new Error('runAudit function not found');                      break;                  case 'organizeTabs': case 'organize-tabs':                      if (typeof organizeTabs === 'function') await organizeTabs(); else throw new Error('organizeTabs function not found');                      break;                  case 'startScribe': case 'start-scribe':                      if (typeof startScribeRecording === 'function') await startScribeRecording(); else throw new Error('startScribeRecording function not found');                      break;              }              if (sendResponse) sendResponse({ received: true, handled: true, action: action });          } catch (execError) {              console.error(`Error executing action ${action} in sidepanel:`, execError);              if (typeof showError === 'function') showError(`Failed to execute '${action}'. ${execError.message}`, 'error');              if (sendResponse) sendResponse({ received: true, handled: false, error: execError.message });          }          break;        case 'tab-updated':          if (AppState.scribeRecording && typeof reinjectScribeContentScript === 'function') {            await reinjectScribeContentScript(message.tabId);          }          break;        default:          console.log('Sidepanel received unhandled message type:', message?.type);          if (typeof sendResponse === 'function') {            sendResponse({ received: true, handled: false, error: 'Unknown message type' });          }      }    } catch (error) {       console.error("Error in sidepanel message handler:", error);       if (typeof sendResponse === 'function') {           try { sendResponse({ received: true, handled: false, error: error.message }); }           catch (e) { console.error("Failed to send error response:", e); }       }    }  })();  return message?.type !== 'ping'; // Keep channel open for async responses}// --- Global Exports ---window.AppState = AppState;window.aiManager = aiManager; // Already declared globally, but re-assign just in case// Expose UI/Utility functions if needed elsewhere (like maybe settings/modal?)window.showStatus = typeof showStatus !== 'undefined' ? showStatus : undefined;window.showError = typeof showError !== 'undefined' ? showError : undefined;window.showSuccess = typeof showSuccess !== 'undefined' ? showSuccess : undefined;window.getCurrentTab = typeof getCurrentTab !== 'undefined' ? getCurrentTab : undefined;window.getTabContent = typeof getTabContent !== 'undefined' ? getTabContent : undefined;window.loadSettings = typeof loadSettings !== 'undefined' ? loadSettings : undefined;window.saveSettings = typeof saveSettings !== 'undefined' ? saveSettings : undefined;console.log('âœ… Core module definitions loaded');// ============================================// SPECTRUM AI PRO ENHANCED v3.2.1// Auditor Module - Website Analysis// ============================================function initializeAuditor() {  document.getElementById('auditButton')?.addEventListener('click', runAudit);  // FIX: Moved button listeners for report toggle to setupReportToggleButton}async function runAudit() {  const auditButton = document.getElementById('auditButton'); // Cache button element  try {    showStatus('auditStatus', 'Starting audit...', true);    if (auditButton) auditButton.disabled = true;    // --- AI Check ---    if (!AppState.settings?.aiEnabled) {        throw new Error("AI features are disabled in settings.");    }    if (!aiManager) { // Ensure aiManager exists (should be initialized in main)        throw new Error("AI Manager not initialized. Cannot run audit.");    }    // FIX: Check current status and attempt to create session, which handles download/errors    // This will show status messages like "Downloading..." or throw if unavailable    await aiManager.createSession(); // Throws if unavailable after trying    // If it didn't throw, AI is ready or download has started/progressing. Proceed.    // --- End AI Check ---    showStatus('auditStatus', 'Fetching page content...', true);    const tab = await getCurrentTab(); // Utility from core/utils    if (!tab) throw new Error('No active tab found.');    // FIX: Add check for restricted URLs    if (tab.url?.startsWith('chrome://') || tab.url?.startsWith('chrome-extension://') || tab.url?.startsWith('about:')) {       throw new Error('Cannot analyze restricted browser pages (e.g., chrome://, extensions).');    }    const content = await getTabContent(tab.id); // Utility from core/utils -> calls service worker    // FIX: Check specifically for content.text existence and type    if (!content || typeof content.text !== 'string') {        // More specific error based on potential scripting issues        throw new Error('Could not retrieve page content. The page might be protected, too complex, or inaccessible to extensions.');    }    showStatus('auditStatus', 'Analyzing with AI (this may take a moment)...', true);    // --- AI Prompt (As defined in README.md) ---    const prompt = `         Analyze the following web page content (first ~10000 chars) for a comprehensive 12-point audit:         Technical, Accessibility, Performance, Security, UX, Content Quality, SEO, Links, Conversion Potential, Analytics Implementation, Competitive Standing (infer), and Mobile Friendliness (infer).         Content Snippet (Title: ${content.title}):         \`\`\`         ${content.text.substring(0, 10000)}         \`\`\`         Respond ONLY with a single, valid JSON object containing two keys: "dashboard" and "markdownReport".         1.  **dashboard**: An object with:             * \`overallScore\` (number 0-100)             * \`health\` (string: "Excellent", "Good", "Fair", or "Poor" based on overallScore)             * \`issues\` (object: \`{ "errors": number, "warnings": number }\` - estimated counts)             * \`scores\` (object with keys for each of the 12 points, values 0-10, e.g., \`{ "technical": 8.5, ... }\`)         2.  **markdownReport**: A string containing a detailed Markdown report. Structure it with:             * '# Audit Report for [Page Title]'             * An overall '## Overview' section (score, health, total issues).             * A section '## [Point Name]' for each of the 12 points, including:                 * Score (e.g., '* **Score**: 8.5/10')                 * A brief 'Assessment' (1-2 sentences).                 * Bulleted '* **Issues**:' (if any identified).                 * Bulleted '* **Recommendations**:' (actionable advice).         Example JSON structure:         {           "dashboard": {             "overallScore": 78, "health": "Good", "issues": { "errors": 2, "warnings": 5 },             "scores": { "technical": 8, "accessibility": 7, "performance": 8, "security": 9, "ux": 7.5, "content": 8, "seo": 7, "links": 8, "conversion": 6.5, "analytics": 7, "competitive": 7, "mobile": 8.5 }           },           "markdownReport": "# Audit Report for Example Page\\n\\n## Overview\\n* Score: 78/100 (Good)\\n* Issues: 2 Errors, 5 Warnings\\n\\n## Technical\\n* **Score**: 8/10\\n* Assessment: Generally sound technical foundation.\\n* **Issues**:\\n  - Minor console errors detected.\\n* **Recommendations**:\\n  - Resolve console errors.\\n..."         }         `;    const response = await aiManager.prompt(prompt);    // --- End AI Prompt ---    let auditResult;    try {        // FIX: More robust JSON extraction - look for ```json ... ``` block or a standalone {} block        const jsonMatch = response.match(/```json\s*([\s\S]*?)\s*```|(\{[\s\S]*\})/);        if (!jsonMatch || (!jsonMatch[1] && !jsonMatch[2])) {             // If no clear JSON block, try parsing the whole response, it might be just the JSON             try {                 auditResult = JSON.parse(response);             } catch (e) {                 throw new Error("AI response did not contain a valid JSON object or ```json``` block.");             }        } else {            const jsonString = jsonMatch[1] || jsonMatch[2]; // Get content from either capture group            auditResult = JSON.parse(jsonString);        }        // Basic validation of the parsed JSON structure        if (!auditResult.dashboard || typeof auditResult.dashboard !== 'object' ||            !auditResult.markdownReport || typeof auditResult.markdownReport !== 'string' ||            !auditResult.dashboard.scores || typeof auditResult.dashboard.scores !== 'object' ||            typeof auditResult.dashboard.overallScore !== 'number' ||            typeof auditResult.dashboard.health !== 'string' ||            !auditResult.dashboard.issues || typeof auditResult.dashboard.issues !== 'object') {            throw new Error("JSON response missing required fields or has incorrect types (dashboard, markdownReport, dashboard.scores, overallScore, health, issues).");        }        console.log("Parsed AI Audit Result:", auditResult.dashboard);    } catch (parseError) {        console.error("Failed to parse AI audit response:", response, parseError);        // Provide more context in the error shown to the user        throw new Error(`AI response format error: ${parseError.message}. AI response started with: ${response.substring(0, 200)}...`);    }    // --- Update State & UI ---    AppState.auditData = auditResult.dashboard;    AppState.auditReport = auditResult.markdownReport;    showStatus('auditStatus', '', false); // Hide status/loader    displayAuditDashboard(AppState.auditData); // Update dashboard UI    displayAuditReport(AppState.auditReport); // Populate the (initially hidden) report div    const toggleButton = document.getElementById('toggleReportButton'); // Show toggle button    if (toggleButton) toggleButton.style.display = 'block';    showSuccess('Audit completed successfully! âœ¨');    // FIX: Add message to chat after successful audit    if (typeof addChatMessage === 'function') {        addChatMessage(document.getElementById('auditorChatMessages'), 'Audit complete! Review the dashboard and report. Feel free to ask me questions about the findings.', 'assistant');    }    // --- Save to History ---     if (typeof saveAuditReport === 'function') {       const reportToSave = {           id: Date.now() + Math.random(), // Simple unique-ish ID           url: tab.url,           title: content.title, // Save title too           date: new Date().toISOString(),           data: AppState.auditData, // The dashboard data object           report: AppState.auditReport // The markdown string       };       await saveAuditReport(reportToSave); // Function from history module       if (typeof loadHistory === 'function') loadHistory(); // Refresh history tab display     } else {        console.warn("saveAuditReport function not found (History module might be missing or loaded later).");     }     // --- End Save to History ---   } catch (error) {     console.error('Audit failed:', error);     // FIX: Show specific error messages for common issues     if (error.message.includes('Could not retrieve page content') || error.message.includes('Cannot access page content') || error.message.includes('restricted browser pages')) {        showError(error.message, 'error'); // Show specific content error     } else if (error.message.includes('AI model is not available') || error.message.includes('AI Model is not ready')) {         showError(`Audit failed: ${error.message}. Please check the Setup page.`, 'error'); // Specific AI error     }      else {        showError(`Audit failed: ${error.message}`, 'error'); // Generic error     }     // Reset UI to initial state on error     document.getElementById('dashboardContainer').style.display = 'none';     document.getElementById('auditReportContent').style.display = 'none';     document.getElementById('toggleReportButton').style.display = 'none';     const placeholder = document.getElementById('initialPlaceholder');     if(placeholder) placeholder.style.display = 'block'; // Show placeholder again   } finally {     showStatus('auditStatus', '', false); // Ensure status is always hidden at the end     if (auditButton) auditButton.disabled = false; // Re-enable button   } }// Displays the dashboard view with scores and chartsfunction displayAuditDashboard(data) {  if (!data) {      showError("No audit data to display.", "warning");      document.getElementById('initialPlaceholder').style.display = 'block';      document.getElementById('dashboardContainer').style.display = 'none';      return;  }  document.getElementById('initialPlaceholder').style.display = 'none';  const dashboardContainer = document.getElementById('dashboardContainer');  dashboardContainer.style.display = 'block';  document.getElementById('auditReportContent').style.display = 'none'; // Ensure report view is hidden initially  document.getElementById('resultsTitle').textContent = `ðŸ“Š Audit Dashboard`; // Reset title  // --- Populate Stat Cards ---  // FIX: Use nullish coalescing for safer defaults  document.getElementById('overallScore').textContent = data.overallScore?.toFixed(0) ?? '--';  document.getElementById('healthStatus').textContent = data.health ?? 'Unknown';  document.getElementById('errorCount').textContent = data.issues?.errors ?? '0';  document.getElementById('warningCount').textContent = data.issues?.warnings ?? '0';  // Apply score class to overall score badge visual  const healthBadge = document.getElementById('healthStatus');  if (healthBadge) {     healthBadge.className = `stat-badge badge-${(data.health || 'unknown').toLowerCase()}`; // Use health string directly for class     healthBadge.textContent = data.health ?? 'Unknown';  }  // --- Populate Detailed Scores Grid ---  const detailedScoresGrid = document.getElementById('detailedScoresGrid');  if (detailedScoresGrid && data.scores) {      detailedScoresGrid.innerHTML = ''; // Clear previous grid items      Object.entries(data.scores).forEach(([key, value]) => {          const scoreItem = document.createElement('div');          scoreItem.className = 'score-item';          // Scale 0-10 score to 0-100 for getScoreClass utility          const scoreClass = getScoreClass((value ?? 0) * 10);          scoreItem.innerHTML = `              <div class="score-header">                  <span>${key.charAt(0).toUpperCase() + key.slice(1).replace(/([A-Z])/g, ' $1')}</span>                  <span class="score-value">${value?.toFixed(1) ?? '--'} / 10</span>              </div>              <div class="score-bar-container">                  <div class="score-bar score-bar-${scoreClass}" style="width: ${Math.max(0, Math.min(100, (value ?? 0) * 10))}%;" title="Score: ${value?.toFixed(1) ?? '--'}"></div>              </div>          `;          detailedScoresGrid.appendChild(scoreItem);      });  } else if (detailedScoresGrid) {       detailedScoresGrid.innerHTML = '<p>Detailed scores unavailable.</p>';  }  // --- Chart.js Integration ---  // Health Donut Chart  const healthChartCtx = document.getElementById('healthChart')?.getContext('2d');  if (healthChartCtx && window.Chart && data.issues) {      // Destroy previous chart instance if it exists      if (AppState.charts.healthChart instanceof Chart) AppState.charts.healthChart.destroy();      const totalIssues = (data.issues.errors ?? 0) + (data.issues.warnings ?? 0);      AppState.charts.healthChart = new Chart(healthChartCtx, {          type: 'doughnut',          data: {              labels: ['Errors', 'Warnings', 'Good'],              datasets: [{                  data: [                      data.issues.errors ?? 0,                      data.issues.warnings ?? 0,                      Math.max(0, 100 - totalIssues*5) // Rough estimate for 'Good' part, assuming max ~20 issues = 0 good                  ],                  backgroundColor: ['var(--error)', 'var(--warning)', 'var(--success)'],                  borderWidth: 0              }]          },          options: {              responsive: true,              maintainAspectRatio: false,              cutout: '70%',              plugins: {                  legend: { display: false },                  tooltip: { enabled: false } // Disable tooltips for this simple chart              }          }      });  }  // Issue Breakdown Bar Chart  const issueChartCtx = document.getElementById('issueChart')?.getContext('2d');    if (issueChartCtx && window.Chart && data.scores) {        // Destroy previous chart instance if it exists        if (AppState.charts.issueChart instanceof Chart) AppState.charts.issueChart.destroy();        AppState.charts.issueChart = new Chart(issueChartCtx, {            type: 'bar',            data: {                labels: Object.keys(data.scores).map(k => k.charAt(0).toUpperCase() + k.slice(1).replace(/([A-Z])/g, ' $1')), // Format labels                datasets: [{                    label: 'Score (0-10)',                    data: Object.values(data.scores),                    backgroundColor: Object.values(data.scores).map(s => {                        const scoreClass = getScoreClass((s ?? 0) * 10);                        if (scoreClass === 'excellent') return 'var(--success)';                        if (scoreClass === 'good') return 'var(--accent)';                        if (scoreClass === 'fair') return 'var(--warning)';                        return 'var(--error)';                    }),                    borderRadius: 4,                    borderSkipped: false, // Ensure radius applies correctly                }]            },            options: {                responsive: true,                maintainAspectRatio: false, // Allow non-square aspect ratio                indexAxis: 'y', // Horizontal bars for better readability                plugins: {                    legend: { display: false }, // No legend needed for single dataset                     tooltip: { // Customize tooltips                         callbacks: {                            label: (context) => ` Score: ${context.parsed.x?.toFixed(1) ?? '--'} / 10`                         }                    }                },                scales: {                     x: { // Value axis (now horizontal)                        beginAtZero: true,                        max: 10,                        grid: { color: 'var(--border)' },                        ticks: { color: 'var(--text-secondary)', stepSize: 2 }                    },                    y: { // Category axis (now vertical)                         grid: { display: false }, // Cleaner look                         ticks: { color: 'var(--text-primary)' }                    }                }            }        });    }  // --- End Chart.js ---  setupReportToggleButton(); // Ensure toggle button works correctly}// Renders the Markdown report into the designated divfunction displayAuditReport(markdownContent) {   const reportContentDiv = document.getElementById('auditReportContent');   if (reportContentDiv) {       // Use the 'marked' parser (defined in utils/core)       reportContentDiv.innerHTML = marked.parse(markdownContent || "<p>No detailed report available.</p>");   } else {       console.error("Audit report content element ('auditReportContent') not found in HTML.");   }}// Sets up the event listener for the dashboard/report toggle buttonfunction setupReportToggleButton() {   const toggleButton = document.getElementById('toggleReportButton');   const dashboardContainer = document.getElementById('dashboardContainer');   const auditReportContent = document.getElementById('auditReportContent');   if (!toggleButton || !dashboardContainer || !auditReportContent) {       console.warn("Could not find elements required for report toggle button setup.");       return;   }   // FIX: Clone and replace the button to remove previous listeners reliably   const newButton = toggleButton.cloneNode(true);   toggleButton.parentNode.replaceChild(newButton, toggleButton);   newButton.addEventListener('click', () => {       const isReportHidden = auditReportContent.style.display === 'none' || auditReportContent.style.display === '';       if (isReportHidden) {           // Show Report, Hide Dashboard           auditReportContent.style.display = 'block';           dashboardContainer.style.display = 'none';           newButton.textContent = 'ðŸ“Š View Dashboard';           document.getElementById('resultsTitle').textContent = 'ðŸ“„ Detailed Audit Report';       } else {           // Show Dashboard, Hide Report           auditReportContent.style.display = 'none';           dashboardContainer.style.display = 'block';           newButton.textContent = 'ðŸ“„ View Detailed Report';           document.getElementById('resultsTitle').textContent = 'ðŸ“Š Audit Dashboard';       }   });    // Set initial button text based on the dashboard's initial display state    const isDashboardVisibleInitially = dashboardContainer.style.display === 'block';    if (isDashboardVisibleInitially) {        newButton.textContent = 'ðŸ“„ View Detailed Report';    } else {        newButton.textContent = 'ðŸ“Š View Dashboard';    }}console.log('âœ… Auditor module definitions loaded');// Expose functions globally if they need to be called from elsewhere (like history module)window.runAudit = runAudit;window.displayAuditDashboard = displayAuditDashboard;window.displayAuditReport = displayAuditReport; // Expose report rendering// ============================================// SPECTRUM AI PRO ENHANCED v3.2.1// Organizer Module - Intelligent Tab Grouping (FIXED)// ============================================function initializeOrganizer() {  document.getElementById('organizeTabsButton')?.addEventListener('click', organizeTabs);  // Add listeners for all contextual action buttons using event delegation on the panel   const actionsPanel = document.getElementById('organizerActionsPanel');   if (actionsPanel) {      actionsPanel.addEventListener('click', (e) => {          if (e.target.tagName === 'BUTTON' && e.target.dataset.action) {              performGroupAction(e.target.dataset.action);          }      });   }   // Assign data-action attributes to buttons   document.getElementById('summarizeGroupButton')?.setAttribute('data-action', 'summarize');   document.getElementById('extractDataButton')?.setAttribute('data-action', 'extract');   document.getElementById('findContactsButton')?.setAttribute('data-action', 'contacts');   document.getElementById('analyzeContentButton')?.setAttribute('data-action', 'analyze');   document.getElementById('compareGroupButton')?.setAttribute('data-action', 'compare');   document.getElementById('predictGroupButton')?.setAttribute('data-action', 'predict');}async function organizeTabs() {  const organizeButton = document.getElementById('organizeTabsButton');  const organizerResultsElement = document.getElementById('organizerResults');  const placeholder = document.getElementById('initialPlaceholder'); // Assume placeholder exists  try {    showStatus('organizerStatus', 'Analyzing tabs...', true);    if (organizeButton) organizeButton.disabled = true;    if (placeholder) placeholder.style.display = 'none'; // Hide placeholder    if (organizerResultsElement) organizerResultsElement.innerHTML = '<div class="loader"></div>'; // Show loader    // Determine if AI should be used    const useAI = AppState.settings?.aiEnabled;    let aiReady = false;    if (useAI && aiManager) {        try {            // Attempt to initialize/check AI, don't throw error here, fallback later            await aiManager.initialize(); // Updates aiManager.availability            aiReady = aiManager.availability === 'readily';            if (!aiReady && aiManager.availability !== 'downloadable' && aiManager.availability !== 'downloading') {                 showError("AI not ready. Using basic domain grouping. Check Setup.", "warning");            } else if (!aiReady) {                 showError("AI model needs download. Click an AI action to start. Using domain grouping for now.", "info");            }        } catch (initError) {             console.warn("AI initialization check failed:", initError);             showError("AI check failed. Using basic domain grouping.", "warning");             aiReady = false;        }    } else if (useAI && !aiManager) {         showError("AI Manager not initialized. Using basic domain grouping.", "warning");    } else if (!useAI) {         showError("AI features disabled. Using basic domain grouping.", "info");    }    // Always fetch tabs first    const tabs = await chrome.tabs.query({ currentWindow: true, pinned: false });    const validTabs = tabs.filter(tab => tab.id && tab.url && !tab.url.startsWith('chrome://') && !tab.url.startsWith('chrome-extension://') && !tab.url.startsWith('about:'));    if (validTabs.length < 2) {      throw new Error('Need at least 2 open tabs (excluding special pages like chrome://) to organize.');    }    let groups;    if (useAI && aiReady) {        showStatus('organizerStatus', `Found ${validTabs.length} tabs. Grouping with AI...`, true);        try {            // FIX: Add try...catch around AI specific logic            await aiManager.createSession(); // Ensure session ready, triggers download if needed            groups = await generateTabGroups(validTabs); // AI grouping        } catch (aiError) {             console.error("AI Grouping failed, falling back:", aiError);             showError(`AI grouping failed (${aiError.message}). Falling back to domain grouping.`, 'warning');             groups = generateFallbackGroups(validTabs); // Fallback on AI error        }    } else {        // Use fallback if AI disabled, unavailable, or errored during init check        groups = generateFallbackGroups(validTabs);    }    // --- Update State & UI ---    AppState.organizerGroups = groups;    AppState.selectedGroup = null; // Reset selection    displayOrganizerResults(groups); // Update the results panel display    resetOrganizerActions(); // Reset actions panel state (disables buttons)    // Only show actions panel if groups were generated    const actionsPanel = document.getElementById('organizerActionsPanel');    if (actionsPanel) actionsPanel.style.display = groups.length > 0 ? 'block' : 'none';    const resultsContainer = document.getElementById('organizerResults');     if (resultsContainer) resultsContainer.style.display = 'block'; // Ensure results are visible    showSuccess(`Suggested ${groups.length} groups for ${validTabs.length} tabs ${useAI && aiReady ? '(using AI)' : '(using domain grouping)'}.`);  } catch (error) {    console.error('Organize tabs error:', error);    showError(error.message || 'Failed to organize tabs.', 'error');    if (organizerResultsElement) {      // Show error message within the results area      organizerResultsElement.innerHTML = `<p class="placeholder error" style="padding: 20px;">Could not organize tabs: ${error.message}</p>`;    }     const actionsPanel = document.getElementById('organizerActionsPanel');     if (actionsPanel) actionsPanel.style.display = 'none'; // Hide actions on error  } finally {    showStatus('organizerStatus', '', false); // Hide status message/loader    if (organizeButton) organizeButton.disabled = false; // Re-enable button  }}// Generates tab groups using AIasync function generateTabGroups(tabs) {  // Map tabs to a simpler format for the prompt, including a local ID  const tabInfo = tabs.map((tab, i) => ({    localId: i + 1, // 1-based index for the prompt    id: tab.id,     // Actual Chrome tab ID    title: tab.title?.substring(0, 100) || '', // Limit title length    url: tab.url,    hostname: getHostname(tab.url), // Use utility function    favIconUrl: tab.favIconUrl // Include favicon URL  }));  const prompt = `Analyze these browser tabs and group them intelligently by topic, purpose, or primary domain.Tabs:${tabInfo.map(t => `${t.localId}. ${t.title} (${t.hostname || 'No Hostname'})`).join('\n')}IMPORTANT: Respond ONLY with valid JSON in this exact format:{  "groups": [    {      "name": "Concise Group Name (1-3 words)",      "tabIds": [1, 3, 5],      "confidence": 85    },    // ... potentially more groups  ]}Rules:- "tabIds" MUST be an array of the numerical local IDs listed above.- "name" must be concise (1-3 words).- "confidence" is your estimated certainty (0-100) that the group is coherent.- Each tab should ideally be in only ONE group. If a tab doesn't fit well, omit it.- Aim for 2-6 meaningful groups based on common themes or tasks.`;  // FIX: No try...catch here, let it bubble up to organizeTabs for fallback  const response = await aiManager.prompt(prompt); // Assumes aiManager is ready  let data;  try {      // More robust JSON extraction      const jsonMatch = response.match(/```json\s*([\s\S]*?)\s*```|(\{[\s\S]*\})/);       if (!jsonMatch || (!jsonMatch[1] && !jsonMatch[2])) {           // If no clear JSON block, try parsing the whole response           try { data = JSON.parse(response); }           catch (e) { throw new Error("No JSON object or ```json``` block found in the AI response."); }      } else {           const jsonString = jsonMatch[1] || jsonMatch[2];           data = JSON.parse(jsonString);      }      // Validate the parsed structure      if (!data || !Array.isArray(data.groups)) {           throw new Error("Parsed JSON is invalid or missing the 'groups' array.");      }  } catch (parseError) {      console.error("Failed to parse AI response for grouping:", response, parseError);      throw new Error(`AI response format error: ${parseError.message}`);  }  // Map localIds back to actual Chrome tab IDs and include full tab details  return data.groups    .map(group => {      // Find the full tab info objects corresponding to the local IDs      const tabsInGroup = (group.tabIds || [])          .map(localId => tabInfo.find(t => t.localId === localId))          .filter(Boolean); // Filter out any undefined results (if AI hallucinates an ID)      // If no valid tabs were found for the group's IDs, discard the group silently      if (tabsInGroup.length === 0) return null;      return {          name: group.name || 'Unnamed Group', // Provide default name          confidence: group.confidence || 50, // Default confidence          tabIds: tabsInGroup.map(t => t.id), // Use actual Chrome tab IDs now          tabs: tabsInGroup // Store the full tab info objects      };    })    .filter(Boolean); // Remove any null groups (those with no valid tabs)}// Fallback grouping function (groups by hostname)// FIX: Safely handle undefined hostname and domain cleaningfunction generateFallbackGroups(tabs) { // Accepts the full tab objects directly  const domainGroups = {};  tabs.forEach(tab => {    // FIX: Safely get hostname using utility, provide fallback    const hostname = getHostname(tab.url); // Use utility    const domain = hostname || 'other'; // Group tabs without hostname under 'other'    // FIX: Only call replace on strings    const cleanDomain = typeof domain === 'string' ? domain.replace(/^www\./, '') : domain;    if (!domainGroups[cleanDomain]) {      // Create a new group for this domain      const name = typeof cleanDomain === 'string' ? cleanDomain.split('.')[0] : 'Other'; // Use first part of domain or 'Other'      domainGroups[cleanDomain] = {        name: name.charAt(0).toUpperCase() + name.slice(1), // Capitalize        tabIds: [], // Will store Chrome tab IDs        tabs: [],   // Will store tab info objects        confidence: 50 // Lower confidence for fallback      };    }    // Add tab to the group    domainGroups[cleanDomain].tabIds.push(tab.id);    domainGroups[cleanDomain].tabs.push(tab);  });  return Object.values(domainGroups); // Return array of group objects}// Displays the suggested groups in the results panelfunction displayOrganizerResults(groups) {  const resultsDiv = document.getElementById('organizerResults');  if (!resultsDiv) {      console.error("Organizer results container ('organizerResults') not found.");      return;  }  resultsDiv.innerHTML = ''; // Clear previous results or loader  if (!groups || groups.length === 0) {    resultsDiv.innerHTML = '<p class="placeholder">No groups were suggested. Try opening more related tabs.</p>';    return;  }  groups.forEach((group, index) => {    const card = document.createElement('div');    card.className = 'organizer-group group-card';    card.dataset.groupIndex = index; // Store index for event listeners    const confidenceClass = getScoreClass(group.confidence || 0);    // Generate list items for tabs, including favicons and escaping HTML    const tabListHtml = (group.tabs || []).map(tab => `      <li>        <img src="${tab.favIconUrl || 'icons/icon16.png'}" alt="" class="favicon" style="width: 16px; height: 16px; margin-right: 8px; vertical-align: middle; object-fit: contain;">        ${escapeHtml(tab.title || tab.url)}      </li>`).join('');    card.innerHTML = `      <div class="organizer-group-header">         <h3 title="${escapeHtml(group.name)}">${escapeHtml(group.name)}</h3>        <span class="confidence-badge confidence-${confidenceClass}" title="AI Confidence">${group.confidence}%</span>      </div>      <ul style="max-height: 150px; overflow-y: auto; margin-bottom: 12px;">${tabListHtml}</ul>      <div class="group-actions" style="margin-top: auto;"> <button class="primary-button create-group-btn" data-group-index="${index}" style="font-size: 13px; padding: 8px 12px;">âœ¨ Create Group</button>      </div>    `;    resultsDiv.appendChild(card);  });  // --- Add Event Listeners using Event Delegation on the resultsDiv ---  resultsDiv.addEventListener('click', async (e) => {      const card = e.target.closest('.organizer-group.group-card');      const createButton = e.target.closest('.create-group-btn');      if (createButton && card) {           // Handle "Create Group" button click          e.stopPropagation(); // Prevent card selection          const index = parseInt(createButton.dataset.groupIndex, 10);          if (!isNaN(index)) {            createButton.textContent = 'Creating...';            createButton.disabled = true;            await createChromeTabGroup(index); // This handles success/error UI updates internally          }      } else if (card) {          // Handle clicking the card itself to select it          const index = parseInt(card.dataset.groupIndex, 10);          if (!isNaN(index)) {            selectGroup(index);          }      }  });}// Resets the action panel and selection statefunction resetOrganizerActions() {    // Remove 'selected' class from all cards    document.querySelectorAll('.organizer-group.group-card').forEach(card => card.classList.remove('selected'));    // Reset selected group in state    AppState.selectedGroup = null;    // Disable all action buttons    const actionButtons = document.querySelectorAll('#organizerActionsPanel .ai-action-button');    actionButtons.forEach(btn => btn.disabled = true);    // Reset context text    const contextText = document.getElementById('organizerActionContext');    if(contextText) contextText.textContent = 'Select a group above to enable AI actions.';    // Clear any previous action results    const resultsDiv = document.getElementById('groupActionResults');    if (resultsDiv) resultsDiv.innerHTML = '';}// Creates an actual Chrome tab group using the service workerasync function createChromeTabGroup(groupIndex) {  // Validate group index and data  if (groupIndex < 0 || !AppState.organizerGroups || groupIndex >= AppState.organizerGroups.length) {      console.error("Invalid group index for createChromeTabGroup:", groupIndex);      return;  }  const group = AppState.organizerGroups[groupIndex];  if (!group || !group.tabIds || group.tabIds.length === 0) {      showError("Cannot create group: Invalid group data or no tabs.", 'error');      return;  }  const card = document.querySelector(`.organizer-group[data-group-index="${groupIndex}"]`);  const button = card?.querySelector('.create-group-btn'); // Get button for potential re-enabling  try {    // Send message to service worker to perform the grouping action    const response = await chrome.runtime.sendMessage({      type: 'create-tab-group',      tabIds: group.tabIds,      groupName: group.name    });    // Handle potential errors during message sending itself    if (chrome.runtime.lastError) {        throw new Error(`Chrome runtime error: ${chrome.runtime.lastError.message}`);    }    if (response.success) {      showSuccess(`Created Chrome tab group: "${group.name}"`);      // Update UI for the created group card      if (card) {          card.style.opacity = '0.5'; // Visually indicate it's been processed          card.style.pointerEvents = 'none'; // Prevent re-clicking          card.classList.remove('selected'); // Deselect if selected          button?.remove(); // Remove create button           // If this was the selected group, reset the action panel           if (AppState.selectedGroup === groupIndex) resetOrganizerActions();      }    } else {      // Handle errors reported back by the service worker      throw new Error(response.error || 'Unknown error occurred in service worker during group creation');    }  } catch (error) {    console.error('Create group error:', error);    showError(`Failed to create tab group: ${error.message}.`, 'error');     // Re-enable button on failure     if (button) {         button.textContent = 'âœ¨ Create Group';         button.disabled = false;     }  }}// Selects a group for contextual actionsfunction selectGroup(groupIndex) {  // Validate index  if (groupIndex < 0 || !AppState.organizerGroups || groupIndex >= AppState.organizerGroups.length) {      console.warn("Attempted to select invalid group index:", groupIndex);      return;  }  // If clicking the already selected group, deselect it  if (groupIndex === AppState.selectedGroup) {      resetOrganizerActions();      return;  }  AppState.selectedGroup = groupIndex;  const group = AppState.organizerGroups[groupIndex];  // Highlight the selected card and unhighlight others  document.querySelectorAll('.organizer-group.group-card').forEach((card, i) => {    card.classList.toggle('selected', i === groupIndex);  });  // Enable action buttons   const actionButtons = document.querySelectorAll('#organizerActionsPanel .ai-action-button');   actionButtons.forEach(btn => btn.disabled = false);  // Update context text  const contextText = document.getElementById('organizerActionContext');   if(contextText) contextText.textContent =    `Actions for: ${escapeHtml(group.name)} (${group.tabs.length} tabs)`;  // Clear previous action results  const resultsDiv = document.getElementById('groupActionResults');  if (resultsDiv) resultsDiv.innerHTML = '';}// Performs the selected AI action on the currently selected groupasync function performGroupAction(actionType) {  if (AppState.selectedGroup === null || !AppState.organizerGroups || AppState.selectedGroup >= AppState.organizerGroups.length) {       return showError('Please select a suggested group first before running an action.', 'warning');  }  const group = AppState.organizerGroups[AppState.selectedGroup];  const resultsDiv = document.getElementById('groupActionResults');  if (!resultsDiv) return;  // Find the specific button clicked using data-action attribute  const actionButton = document.querySelector(`#organizerActionsPanel button[data-action="${actionType}"]`);  if (actionButton) actionButton.disabled = true; // Disable the button during processing  try {    resultsDiv.innerHTML = '<div class="loader"></div><p style="text-align: center; color: var(--text-secondary);">Performing AI action...</p>';    // --- AI Check ---    if (!AppState.settings?.aiEnabled) {        throw new Error("AI features are disabled in settings.");    }    if (!aiManager) {        throw new Error("AI Manager not initialized.");    }    // FIX: Add try...catch specifically around createSession    try {        await aiManager.createSession(); // Attempt to create session, handles download/errors    } catch (aiError) {        throw new Error(`AI Model Error: ${aiError.message}. Check Setup page.`); // Rethrow with specific context    }    // --- End AI Check ---    let result;    // Call the appropriate function based on actionType    // FIX: Added try...catch around each specific action call for better error context    try {        switch (actionType) {          case 'summarize': result = await summarizeGroup(group); break;          case 'extract': result = await extractGroupData(group); break;          case 'contacts': result = await findGroupContacts(group); break;          case 'analyze': result = await analyzeGroupContent(group); break;          case 'compare': result = await compareGroup(group); break;          case 'predict': result = await predictGroupTrends(group); break;          default: throw new Error(`Unknown action type: ${actionType}`);        }    } catch (actionError) {         // Re-throw action-specific errors (like content fetching failure)         throw actionError;    }    // Display the result    resultsDiv.innerHTML = `      <div class="action-result panel-section">        <h4 class="section-title">${getActionTitle(actionType)}</h4>        <div class="result-content">${formatActionResult(result)}</div>      </div>    `;    showSuccess(`${getActionTitle(actionType)} completed!`);  } catch (error) {    console.error(`Group action '${actionType}' error:`, error);    // FIX: Show specific error in the results area    resultsDiv.innerHTML = `<p class="placeholder error" style="padding: 20px;">Action '${actionType}' failed: ${error.message}</p>`;    showError(`Action failed: ${error.message}`, 'error');  } finally {     // Re-enable the button     if (actionButton) actionButton.disabled = false;  }}// --- Action Implementations (summarize, extract, contacts, analyze) ---// These functions now include getGroupContent call and use aiManager.prompt// Fetches content for tabs in a groupasync function getGroupContent(group, maxTabs = 5, maxCharsPerTab = 1500) {    const contents = [];    // Limit the number of tabs processed    const tabsToProcess = group.tabs.slice(0, maxTabs);    showStatus('organizerStatus', `Fetching content for ${tabsToProcess.length} tabs (max ${maxTabs})...`, true);    // Fetch content concurrently    const contentPromises = tabsToProcess.map(tab =>        getTabContent(tab.id).catch(error => { // Use utility function from core            console.warn(`Failed to get content for tab ${tab.id} (${tab.title}): ${error.message}`);            return null; // Don't fail all if one tab is inaccessible        })    );    const results = await Promise.all(contentPromises);    results.forEach((content, index) => {        if (content && content.text) {            contents.push({                title: tabsToProcess[index].title || 'Untitled',                text: content.text.substring(0, maxCharsPerTab) // Limit characters per tab            });        }    });    showStatus('organizerStatus', '', false); // Hide status    if (contents.length === 0) {      throw new Error(`Could not retrieve readable content from any of the first ${maxTabs} tabs. Ensure pages are loaded and accessible.`);    }    return contents;}async function summarizeGroup(group) {  const contents = await getGroupContent(group, 5, 1000); // Limit context size  const prompt = `Summarize the common themes, key topics, and main insights from these ${contents.length} web page snippets (grouped under the topic "${group.name}").${contents.map((c, i) => `--- Snippet from Tab ${i + 1}: ${c.title} ---${c.text}`).join('\n')}Provide a concise summary formatted in Markdown:1.  **Overall Theme:** (1-2 sentences max)2.  **Key Topics Covered:** (Bulleted list)3.  **Main Insights/Takeaways:** (Bulleted list)4.  **Relationship Between Tabs:** (Brief explanation)`;  return await aiManager.prompt(prompt);}async function extractGroupData(group) {  const contents = await getGroupContent(group, 5, 1500);  const prompt = `Extract key data points, statistics, names (people, organizations, locations), dates, and specific factual information from these ${contents.length} text snippets (related to "${group.name}").${contents.map((c, i) => `--- Snippet from Tab ${i + 1}: ${c.title} ---${c.text}`).join('\n')}Format the output clearly in Markdown, grouping similar items:- **Key Statistics & Numbers:** (e.g., percentages, counts, monetary values)- **Important Dates Mentioned:**- **Notable Names/Entities:** (People, Organizations, Products, Locations)- **Specific Factual Claims:** (Brief, verifiable statements)If a category has no relevant data, state "None found". Be precise and extract only from the provided text.`;  return await aiManager.prompt(prompt);}async function findGroupContacts(group) {  const contents = await getGroupContent(group, 5, 2000);  const prompt = `Scan the following text snippets (from tabs related to "${group.name}") and extract any potential contact information.${contents.map((c, i) => `--- Snippet from Tab ${i + 1}: ${c.title} ---${c.text}`).join('\n')}Look specifically for:- Email addresses (format: name@domain.com)- LinkedIn profile URLs (containing linkedin.com/in/)- Twitter handles (format: @username)- Phone numbers (various common formats)- Names of people if associated with a company or role mentioned nearby.Format the findings as a Markdown bulleted list. If no contact information is found, explicitly state "No contact information found". Do not guess or infer information not present.`;  return await aiManager.prompt(prompt);}async function analyzeGroupContent(group) {  const contents = await getGroupContent(group, 5, 1000);  const prompt = `Perform a brief content analysis on these ${contents.length} text snippets (grouped under "${group.name}").${contents.map((c, i) => `--- Snippet from Tab ${i + 1}: ${c.title} ---${c.text}`).join('\n')}Analyze and report in Markdown:1.  **Primary Topics & Subtopics:** (Identify the main subjects based *only* on the text)2.  **Overall Sentiment:** (Positive, Negative, Neutral, Mixed?)3.  **Potential Target Audience:** (Infer who this content is likely written for)4.  **Content Gaps/Unanswered Questions:** (What seems missing or unclear based *only* on these snippets?)`;  return await aiManager.prompt(prompt);}// FIX: Added Compare and Predict functions based on READMEasync function compareGroup(group) {  if (group.tabs.length < 2) return 'Please select a group with at least 2 tabs to compare.';  const contents = await getGroupContent(group, 4, 800); // Compare up to 4 tabs, limit text  if (contents.length < 2) throw new Error("Could not retrieve content from at least two tabs for comparison.");  const prompt = `Compare and contrast the content of these ${contents.length} text snippets (related to "${group.name}"). Focus ONLY on the information present in the snippets.${contents.map((c, i) => `--- Snippet from Tab ${i + 1}: ${c.title} ---${c.text}`).join('\n')}Provide a comparative analysis in Markdown:1.  **Key Similarities:** (Common points, themes, or facts mentioned)2.  **Main Differences:** (Contrasting information, perspectives, or details)3.  **Unique Aspects of Each Snippet:** (What specific info does each provide that others don't?)4.  **(Optional) Which seems most informative based *only* on these snippets?**`;  return await aiManager.prompt(prompt);}async function predictGroupTrends(group) {  const contents = await getGroupContent(group, 5, 1000);  const prompt = `Based *only* on the content within these ${contents.length} text snippets (grouped as "${group.name}"), identify potential trends, future outlooks, key insights, opportunities or challenges mentioned or clearly implied. Do not use external knowledge.${contents.map((c, i) => `--- Snippet from Tab ${i + 1}: ${c.title} ---${c.text}`).join('\n')}Analyze for the following and present in Markdown (State "None apparent" if nothing found):1.  **Emerging Trends Mentioned/Implied:**2.  **Future Predictions or Outlook Stated:**3.  **Key Insights from Collective Content:**4.  **Potential Opportunities/Challenges Highlighted:**`;  return await aiManager.prompt(prompt);}console.log('âœ… Organizer module definitions loaded');window.organizeTabs = organizeTabs; // Expose globally if needed by commands/menus// ============================================// SPECTRUM AI PRO ENHANCED v3.2.1// Scribe Module - Workflow Documentation// ============================================// Global variables specific to Scribe, prefixed for claritylet scribe_lastScreenshotTime = 0;const SCRIBE_SCREENSHOT_DEBOUNCE = 1000; // 1 second debounce for screenshotsfunction initializeScribe() {  document.getElementById('startScribeButton')?.addEventListener('click', startScribeRecording);  document.getElementById('stopScribeButton')?.addEventListener('click', stopScribeRecording);  document.getElementById('clearScribeButton')?.addEventListener('click', clearScribeSteps);  // AI Action Buttons - Using data attributes for delegation  document.getElementById('generalizeWorkflowButton')?.setAttribute('data-action', 'generalize');  document.getElementById('analyzeWorkflowButton')?.setAttribute('data-action', 'analyze');  const scribeActionsPanel = document.getElementById('scribeActionsPanel');  if (scribeActionsPanel) {      scribeActionsPanel.addEventListener('click', (e) => {          if (e.target.tagName === 'BUTTON' && e.target.dataset.action) {              const action = e.target.dataset.action;              if (action === 'generalize') generalizeWorkflow();              else if (action === 'analyze') analyzeWorkflow();          }      });  }  // Export Buttons  document.getElementById('exportScribeTxtButton')?.addEventListener('click', () => exportScribe('txt'));  document.getElementById('exportScribeJsonButton')?.addEventListener('click', () => exportScribe('json'));  document.getElementById('exportScribePdfButton')?.addEventListener('click', () => exportScribe('pdf'));  // Message listener is handled centrally in handleRuntimeMessage (CORE module)}// Start recording user interactionsasync function startScribeRecording() {  const startButton = document.getElementById('startScribeButton');  const stopButton = document.getElementById('stopScribeButton');  const clearButton = document.getElementById('clearScribeButton');  try {    if (AppState.scribeRecording) return; // Prevent double-start    AppState.scribeRecording = true;    AppState.scribeSteps = []; // Clear previous steps    scribe_lastScreenshotTime = 0; // Reset debounce timer    // --- Update UI ---    if (startButton) startButton.disabled = true;    if (stopButton) { stopButton.disabled = false; stopButton.style.display = 'inline-block'; }    if (clearButton) clearButton.disabled = true;    showStatus('scribeStatus', 'ðŸ”´ Recording... Click elements on web pages.', true);    // Clear results areas    const resultsDiv = document.getElementById('scribeResults');    if (resultsDiv) resultsDiv.innerHTML = '<p class="placeholder">Recording interactions...</p>';    const actionResultsDiv = document.getElementById('scribeActionResults');    if (actionResultsDiv) actionResultsDiv.innerHTML = '';    const actionsPanel = document.getElementById('scribeActionsPanel');    if (actionsPanel) actionsPanel.style.display = 'none';    // --- End UI Update ---    // --- AI Check ---    if (!AppState.settings?.aiEnabled) {        throw new Error("AI features are disabled in settings (needed for instructions).");    }    if (!aiManager) {        throw new Error("AI Manager not initialized.");    }    // FIX: Attempt to create session, handles download/errors    await aiManager.createSession(); // Throws if unavailable after trying    // --- End AI Check ---    // --- Get Tab and Inject Script ---    const tab = await getCurrentTab(); // Utility from core/utils    if (!tab || !tab.id || tab.url?.startsWith('chrome://') || tab.url?.startsWith('chrome-extension://') || tab.url?.startsWith('about:')) {      throw new Error('Cannot start recording on this type of page (e.g., Chrome settings, other extensions).');    }    await injectScribeContentScript(tab.id); // Inject CSS and JS    // --- End Inject Script ---    showSuccess('Recording started! Interact with web pages to capture steps.');  } catch (error) {    console.error('Start Scribe recording error:', error);    showError(`Failed to start recording: ${error.message}`, 'error');    // Reset state on failure    AppState.scribeRecording = false;    if (startButton) startButton.disabled = false;    if (stopButton) { stopButton.disabled = true; stopButton.style.display = 'none'; }    if (clearButton) clearButton.disabled = AppState.scribeSteps.length === 0; // Re-enable clear if steps existed    showStatus('scribeStatus', '', false);  }}// Stop recording and process stepsasync function stopScribeRecording() {  if (!AppState.scribeRecording) return; // Prevent double-stop  const startButton = document.getElementById('startScribeButton');  const stopButton = document.getElementById('stopScribeButton');  const clearButton = document.getElementById('clearScribeButton');  try {    AppState.scribeRecording = false; // Set state immediately    // --- Update UI ---    if (startButton) startButton.disabled = false;    if (stopButton) { stopButton.disabled = true; stopButton.style.display = 'none'; }    if (clearButton) clearButton.disabled = (AppState.scribeSteps.length === 0);    showStatus('scribeStatus', 'Processing recorded steps...', true);    // --- End UI Update ---    // --- Stop Content Script ---    // Try to find any active tab where the content script might be running     const tabs = await chrome.tabs.query({ active: true, currentWindow: true });     if (tabs.length > 0 && tabs[0].id) {        try {            await chrome.tabs.sendMessage(tabs[0].id, { type: 'stop-scribe-recording' });            console.log("Sent stop message to content script in active tab.");        } catch(err) {            // Content script might not be injected or tab changed - this is often expected            if (!err.message?.includes("Receiving end does not exist")) {                 console.warn("Could not send stop message to Scribe content script:", err.message);            }        }    }    // --- End Stop Content Script ---    if (AppState.scribeSteps.length === 0) {        showError("No interactions were recorded during this session.", "warning");        displayScribeSteps(); // Show "No steps" message in results        showStatus('scribeStatus', '', false);        return;    }    // --- Generate Guide Title/Summary with AI (if AI is ready) ---    if (AppState.settings?.aiEnabled && aiManager && aiManager.isAvailable === 'readily') {        await generateWorkflowGuide(); // Generates title/summary and updates display    } else {        console.warn("AI not ready or disabled, skipping title/summary generation.");        displayScribeSteps(); // Update display without title/summary    }    // --- End Generate Guide ---    showStatus('scribeStatus', '', false); // Hide status    // Show action buttons now that recording stopped and steps exist    const actionsPanel = document.getElementById('scribeActionsPanel');    if (actionsPanel) actionsPanel.style.display = 'block';    showSuccess(`Recording stopped. Captured ${AppState.scribeSteps.length} steps.`);  } catch (error) {    console.error('Stop Scribe recording error:', error);    showError(`Failed to stop recording or generate guide: ${error.message}`, 'error');    showStatus('scribeStatus', '', false); // Ensure status is hidden on error    // Ensure UI is reset even on error    if (startButton) startButton.disabled = false;    if (stopButton) { stopButton.disabled = true; stopButton.style.display = 'none'; }    displayScribeSteps(); // Update display (might show error or existing steps)  }}// Injects the content script and CSS into the target tabasync function injectScribeContentScript(tabId) {  try {    // Check if script is already injected in this tab context using a flag    const results = await chrome.scripting.executeScript({        target: { tabId: tabId },        func: () => window.hasOwnProperty('__SPECTRUM_SCRIBE_INJECTED__'),    }).catch(err => {        // Handle cases where scripting on the page is disallowed (e.g., chrome web store)        console.warn(`Could not check for existing script in tab ${tabId}: ${err.message}. Assuming not injected.`);        // Return a structure mimicking a failed check        return [{result: false}];    });    // Inject only if the flag is not set (or check failed)    if (!results || !results[0] || !results[0].result) {        console.log(`Injecting Scribe scripts into tab ${tabId}`);        // Inject CSS first (less likely to fail)        await chrome.scripting.insertCSS({            target: { tabId: tabId },            files: ['Content Scripts/scribe.css'] // Path relative to extension root (from manifest)        });        // Inject JavaScript        await chrome.scripting.executeScript({            target: { tabId: tabId },            files: ['Content Scripts/scribe-content.js'] // Path relative to extension root            // world: 'MAIN' // Consider MAIN world if interaction with page scripts is needed, but ISOLATED is safer        });        console.log(`Scribe scripts injected successfully into tab ${tabId}.`);    } else {         console.log(`Scribe content script already present in tab ${tabId}. Attempting to ensure listener is active.`);         // Optionally, send a message to the existing script to ensure it's listening         try {             await chrome.tabs.sendMessage(tabId, { type: 'ensure-scribe-active' });         } catch(err) {             console.warn("Could not ping existing content script, might be inactive:", err.message);         }    }  } catch (error) {    console.error(`Content script injection error in tab ${tabId}:`, error);    // Provide more user-friendly error messages for common cases    if (error.message.includes("Cannot access contents of url")) {       const hostname = getHostname(error.message.split('"')[1] || 'this page'); // Extract URL if possible       throw new Error(`Cannot record on ${hostname}. It might be a restricted page (like chrome:// or the Web Store).`);    } else if (error.message.includes("No target specified")) {         throw new Error(`Target tab (ID: ${tabId}) not found or closed.`);    }    throw new Error(`Failed to inject recorder script: ${error.message}. Try refreshing the page.`);  }}// Re-injects content script if needed after navigationasync function reinjectScribeContentScript(tabId) {  if (!AppState.scribeRecording) return; // Only reinject if currently recording  try {    console.log(`Tab ${tabId} updated, attempting Scribe script reinjection...`);    // Wait a short time for the page to potentially finish loading basic structure    await new Promise(resolve => setTimeout(resolve, 500));    // Get tab info again to ensure it's still a valid target (e.g., not chrome://)    const currentTab = await chrome.tabs.get(tabId).catch(() => null);    if (currentTab && currentTab.url && (currentTab.url.startsWith('http:') || currentTab.url.startsWith('https:'))) {        await injectScribeContentScript(tabId); // Attempt injection (will check if already present)    } else {        console.log(`Skipping reinjection into inaccessible or non-http(s) tab ${tabId} (URL: ${currentTab?.url || 'unknown'})`);    }  } catch (error) {    // Log error but don't stop the overall recording    console.warn(`Scribe re-injection failed for tab ${tabId}:`, error.message);    // Optionally show a non-critical error to the user via toast    // showError("Recorder might miss steps on navigated page due to injection issue.", "warning");  }}// Handles the captured click data received from the content script (via service worker)async function handleClickCapture(clickData, tabId) {  if (!AppState.scribeRecording) {      console.log("Scribe: Ignoring click capture, recording is stopped.");      return;  }  try {    const stepNumber = AppState.scribeSteps.length + 1;    showStatus('scribeStatus', `ðŸ”´ Recording... Capturing Step ${stepNumber}`, true); // Update status    // --- Screenshot Logic ---    let screenshotDataUrl = null;    const now = Date.now();    if (now - scribe_lastScreenshotTime > SCRIBE_SCREENSHOT_DEBOUNCE) {      try {        // Ensure the tabId is valid before capturing        const tabExists = await chrome.tabs.get(tabId).catch(() => null);        if (tabExists) {            screenshotDataUrl = await chrome.tabs.captureVisibleTab(null, { // Capture current tab              format: 'jpeg',              quality: Math.round((AppState.settings?.screenshotQuality || 0.7) * 100) // Use setting            });            scribe_lastScreenshotTime = now;            console.log(`Screenshot captured for step ${stepNumber}`);        } else {             console.warn(`Tab ${tabId} not found for screenshot capture.`);        }      } catch (screenshotError) {           console.warn(`Screenshot capture failed for step ${stepNumber}: ${screenshotError.message}`);           // Don't stop the step, just log the warning      }    } else {        console.log(`Screenshot skipped for step ${stepNumber} (debounced).`);    }    // --- End Screenshot Logic ---    // --- Generate Instruction using AI ---    let instruction = "Click interaction recorded."; // Default fallback    if (AppState.settings?.aiEnabled && aiManager && aiManager.isAvailable === 'readily') {         // No need to check createSession here, assume startScribeRecording ensured readiness        instruction = await generateStepInstruction(clickData, stepNumber);    } else {        console.warn("AI instruction generation skipped (AI disabled or not ready).");        // Generate a basic instruction without AI        let fallback = `Click the ${clickData.tagName.toLowerCase()}`;        if (clickData.text) fallback += ` containing "${clickData.text.substring(0, 30)}"`;        else if (clickData.ariaLabel) fallback += ` labeled "${clickData.ariaLabel}"`;        instruction = fallback + '.';    }    // --- End Instruction Generation ---    // --- Store Step Data ---    const step = {      number: stepNumber,      timestamp: clickData.timestamp || new Date().toISOString(), // Use precise timestamp if available      action: 'click',      element: clickData, // Contains tagName, id, text, ariaLabel, etc.      instruction: instruction,      screenshot: screenshotDataUrl, // Store Data URL      url: clickData.url    };    AppState.scribeSteps.push(step);    // --- End Store Step ---    displayScribeSteps(); // Refresh the UI to show the new step  } catch (error) {    console.error('Error handling captured click:', error);    showError(`Error capturing step ${AppState.scribeSteps.length + 1}: ${error.message}`, 'error');    // Continue recording if possible  } finally {      // Keep showing recording status unless explicitly stopped      if(AppState.scribeRecording) {          showStatus('scribeStatus', `ðŸ”´ Recording... Step ${AppState.scribeSteps.length + 1}`, true);      }  }}// Generates a concise instruction for a recorded step using AIasync function generateStepInstruction(clickData, stepNumber) {  // Create a more descriptive representation of the clicked element for the prompt  let elementDescription = clickData.tagName?.toLowerCase() || 'element';  if (clickData.type && ['button', 'submit', 'checkbox', 'radio', 'text', 'email', 'password', 'search', 'tel', 'url'].includes(clickData.type)) {      elementDescription = clickData.type + (clickData.tagName?.toLowerCase() === 'input' ? ' input' : '');  } else if (clickData.role) {       elementDescription = clickData.role; // Use ARIA role if available  }  if (clickData.id) elementDescription += ` (ID: "${clickData.id}")`;  // else if (clickData.className) elementDescription += ` (Class: "${clickData.className.split(' ')[0]}")`; // Class can be noisy  // Prioritize meaningful text/labels  let textContent = '';  if (clickData.ariaLabel) textContent = ` labeled "${clickData.ariaLabel}"`;  else if (clickData.text && clickData.text.length > 1 && clickData.text.length < 50) textContent = ` containing text "${clickData.text}"`; // Use short, meaningful text  else if (clickData.placeholder) textContent = ` with placeholder "${clickData.placeholder}"`;  else if (clickData.name) textContent = ` named "${clickData.name}"`;  const prompt = `Generate a concise, user-friendly, imperative instruction (starting with an action verb like Click, Select, Enter) for this browser interaction:Interaction: Clicked a ${elementDescription}${textContent}.Page Context: ${getHostname(clickData.url)}Step Number: ${stepNumber}Examples:- Click the 'Login' button.- Select the 'Account Settings' option.- Enter username in the username field.- Click the product image.- Check the 'Remember me' box.Generate ONLY the single instruction sentence:`;  try {    const response = await aiManager.prompt(prompt);    // Basic cleanup: Remove potential "Instruction:" prefix, trim, ensure punctuation.    let instruction = response.replace(/^Instruction:\s*/i, '').trim();    if (instruction && !/[\.\?!]$/.test(instruction)) {        instruction += '.'; // Add period if missing    }    // Fallback if AI gives empty/bad response    return instruction || `Click the ${elementDescription}${textContent}.`;  } catch (error) {    console.error('AI Instruction generation error:', error);    // Construct a reasonable fallback instruction    let fallback = `Click the ${elementDescription}`;     if (textContent) fallback += textContent; // Use the derived textContent    return fallback + '.';  }}// Displays the recorded steps in the UIfunction displayScribeSteps() {  const resultsDiv = document.getElementById('scribeResults');  if (!resultsDiv) return;  const stepsExist = AppState.scribeSteps && AppState.scribeSteps.length > 0;  // Determine button/panel states based on recording status and steps existence  const enableActions = !AppState.scribeRecording && stepsExist;  if (!stepsExist) {    // Show placeholder message based on recording state    resultsDiv.innerHTML = `<p class="placeholder" style="padding-top: 20px;">${AppState.scribeRecording ? 'Recording interactions... Click elements on the page.' : 'No steps recorded yet. Click "Start Recording" to begin.'}</p>`;  } else {    // Generate HTML for each step    const stepsHtml = AppState.scribeSteps.map(step => `      <div class="scribe-step">        <div class="scribe-step-header">          <span class="scribe-step-number">${step.number}</span>          <strong class="step-instruction">${escapeHtml(step.instruction)}</strong>        </div>        ${step.screenshot ? `          <div class="scribe-step-screenshot">            <img src="${step.screenshot}" alt="Step ${step.number} screenshot" loading="lazy" title="Click to view full size (if applicable)">          </div>` : ''}        <div class="scribe-step-details">          <small>URL: ${escapeHtml(getHostname(step.url))}</small>          <small>Element: &lt;${step.element.tagName.toLowerCase()}${step.element.id ? `#${escapeHtml(step.element.id)}` : ''}&gt;</small>          ${step.element.text ? `<small>Text: "${escapeHtml(step.element.text.substring(0, 50))}"</small>` : ''}           ${step.element.ariaLabel ? `<small>Label: "${escapeHtml(step.element.ariaLabel.substring(0, 50))}"</small>` : ''}        </div>      </div>    `).join('');    // Preserve header if it exists, otherwise create placeholder title    const existingHeaderHtml = resultsDiv.querySelector('.workflow-header')?.outerHTML || '';    const guideTitleHtml = !existingHeaderHtml ? '<h3 class="section-title" style="margin-bottom: 10px;">Recorded Workflow Steps</h3>' : '';    resultsDiv.innerHTML = `      ${existingHeaderHtml}      <div class="workflow-guide">        ${guideTitleHtml}        <div class="steps-list">${stepsHtml}</div>      </div>    `;  }  // Update button states  document.getElementById('generalizeWorkflowButton').disabled = !enableActions;  document.getElementById('analyzeWorkflowButton').disabled = !enableActions;  document.getElementById('exportScribeTxtButton').disabled = !enableActions;  document.getElementById('exportScribeJsonButton').disabled = !enableActions;  document.getElementById('exportScribePdfButton').disabled = !enableActions;  // Clear button is enabled if steps exist AND not currently recording  document.getElementById('clearScribeButton').disabled = !stepsExist || AppState.scribeRecording;  // Show/hide action panel based on whether actions are enabled  const actionsPanel = document.getElementById('scribeActionsPanel');  if (actionsPanel) actionsPanel.style.display = enableActions ? 'block' : 'none';   // Show chat container if actions are enabled (meaning recording stopped and steps exist)   const chatContainer = document.getElementById('scribeChatContainer');   if (chatContainer) chatContainer.style.display = enableActions ? 'flex' : 'none';}// Generates a title and summary for the workflow using AIasync function generateWorkflowGuide() {  // Guard clauses  if (!AppState.scribeSteps || AppState.scribeSteps.length === 0 || AppState.scribeRecording) {      displayScribeSteps(); // Just update display if no steps or still recording      return;  }  // FIX: Check AI readiness before proceeding  if (!AppState.settings?.aiEnabled || !aiManager || aiManager.isAvailable !== 'readily') {      console.warn("AI not ready or disabled, skipping title/summary generation.");      displayScribeSteps(); // Update display without new header      return; // Don't show error, just proceed without this feature  }  showStatus('scribeStatus', 'Generating title & summary...', true); // Show status during AI call  const prompt = `Based on the following recorded workflow steps, generate a concise descriptive title (max 10 words) and a brief summary (1-3 sentences) explaining the overall task performed.Workflow Steps:${AppState.scribeSteps.map(s => `${s.number}. ${escapeHtml(s.instruction)}`).join('\n')}Respond ONLY in this exact format, with no extra explanation:Title: [Generated Title Here]Summary: [Generated Summary Here]`;  try {    const response = await aiManager.prompt(prompt); // Assumes AI is ready    // More robust parsing for Title and Summary    const titleMatch = response.match(/^Title:\s*(.*)$/im);    const summaryMatch = response.match(/^Summary:\s*(.*)$/im);    const title = titleMatch ? titleMatch[1].trim() : `Workflow (${AppState.scribeSteps.length} Steps)`;    const summary = summaryMatch ? summaryMatch[1].trim() : `A recorded workflow consisting of ${AppState.scribeSteps.length} steps, captured on ${new Date().toLocaleDateString()}.`;    // Update the UI with the generated header    const resultsDiv = document.getElementById('scribeResults');    if (resultsDiv) {      // Remove old header if exists      const oldHeader = resultsDiv.querySelector('.workflow-header');      if (oldHeader) oldHeader.remove();      // Create and prepend new header      const header = document.createElement('div');      header.className = 'workflow-header panel-section'; // Use panel-section for styling consistency      header.innerHTML = `<h3 class="section-title">${escapeHtml(title)}</h3><p style="color: var(--text-secondary); font-size: 13px;">${escapeHtml(summary)}</p>`;      // Prepend header before the steps list      resultsDiv.insertBefore(header, resultsDiv.firstChild);    }     displayScribeSteps(); // Refresh display including the new header and button states  } catch (error) {    console.error('Error generating workflow title/summary:', error);    showError('Could not generate AI title/summary for the workflow.', 'warning');    displayScribeSteps(); // Refresh display even on error  } finally {      showStatus('scribeStatus', '', false); // Hide status  }}// Generalizes the workflow using AIasync function generalizeWorkflow() {  if (!AppState.scribeSteps || AppState.scribeSteps.length === 0) return showError("No steps recorded to generalize.", "warning");  const actionButton = document.getElementById('generalizeWorkflowButton');  const resultsDiv = document.getElementById('scribeActionResults');  if (!resultsDiv || !actionButton) return;  actionButton.disabled = true;  resultsDiv.innerHTML = '<div class="loader"></div><p style="text-align: center; color: var(--text-secondary);">Generalizing workflow with AI...</p>';  // FIX: Check AI readiness  if (!AppState.settings?.aiEnabled || !aiManager || aiManager.isAvailable !== 'readily') {      resultsDiv.innerHTML = `<p class="placeholder error" style="padding: 20px;">AI features unavailable. Cannot generalize workflow.</p>`;      showError("AI features unavailable. Cannot generalize workflow.", "warning");      actionButton.disabled = false;      return;  }  try {    const prompt = `Take the following specific workflow steps and generalize them into a reusable template. Replace specific user inputs (like names, emails, search terms), data values, or item names (like specific product titles) with clear placeholders in square brackets, e.g., [USERNAME], [EMAIL_ADDRESS], [PRODUCT_NAME], [SEARCH_QUERY]. Keep the core actions and element identifiers (like 'Login button', 'email field').Specific Steps:${AppState.scribeSteps.map(s => `${s.number}. ${escapeHtml(s.instruction)}`).join('\n')}Provide ONLY the generalized steps as a numbered list in Markdown format.`;    const result = await aiManager.prompt(prompt); // Assumes AI is ready    resultsDiv.innerHTML = `      <div class="action-result panel-section">        <h4 class="section-title">ðŸ”„ Generalized Workflow Template</h4>        <div class="result-content">${formatActionResult(result)}</div>      </div>`;    showSuccess('Workflow generalized successfully!');  } catch (error) {    console.error('Generalize workflow error:', error);    resultsDiv.innerHTML = `<p class="placeholder error" style="padding: 20px;">Failed to generalize workflow: ${error.message}</p>`;    showError(`Failed to generalize workflow: ${error.message}`, 'error');  } finally {      actionButton.disabled = false; // Re-enable button  }}// Analyzes the workflow for improvements using AIasync function analyzeWorkflow() {   if (!AppState.scribeSteps || AppState.scribeSteps.length === 0) return showError("No steps recorded to analyze.", "warning");   const actionButton = document.getElementById('analyzeWorkflowButton');   const resultsDiv = document.getElementById('scribeActionResults');   if (!resultsDiv || !actionButton) return;   actionButton.disabled = true;   resultsDiv.innerHTML = '<div class="loader"></div><p style="text-align: center; color: var(--text-secondary);">Analyzing workflow with AI...</p>';  // FIX: Check AI readiness  if (!AppState.settings?.aiEnabled || !aiManager || aiManager.isAvailable !== 'readily') {       resultsDiv.innerHTML = `<p class="placeholder error" style="padding: 20px;">AI features unavailable. Cannot analyze workflow.</p>`;       showError("AI features unavailable. Cannot analyze workflow.", "warning");       actionButton.disabled = false;      return;  }  try {    const prompt = `Analyze the following recorded workflow steps for potential inefficiencies, usability improvements, or alternative approaches. Consider the number of clicks, navigation patterns, and potential for automation or shortcuts.Recorded Steps:${AppState.scribeSteps.map(s => `${s.number}. ${escapeHtml(s.instruction)}`).join('\n')}Provide your analysis in Markdown format, covering (if applicable):1.  **Efficiency Analysis:** Any redundant steps or unnecessary navigation?2.  **Potential Bottlenecks:** Identify steps likely to cause user friction or errors.3.  **Optimization Suggestions:** Offer specific advice for making the workflow smoother or faster.4.  **Alternative Approaches:** Suggest different methods to achieve the same goal if apparent.`;    const result = await aiManager.prompt(prompt); // Assumes AI is ready    resultsDiv.innerHTML = `      <div class="action-result panel-section">        <h4 class="section-title">ðŸ”¬ Workflow Analysis & Optimization Suggestions</h4>        <div class="result-content">${formatActionResult(result)}</div>      </div>`;    showSuccess('Workflow analysis complete!');  } catch (error) {    console.error('Analyze workflow error:', error);    resultsDiv.innerHTML = `<p class="placeholder error" style="padding: 20px;">Failed to analyze workflow: ${error.message}</p>`;    showError(`Failed to analyze workflow: ${error.message}`, 'error');  } finally {       actionButton.disabled = false; // Re-enable button  }}// Clears the currently recorded stepsasync function clearScribeSteps() {  if (AppState.scribeRecording) return showError("Cannot clear steps while recording is active.", "warning");  if (!AppState.scribeSteps || AppState.scribeSteps.length === 0) return showError('No recorded steps to clear.', 'info');  if (confirm('Are you sure you want to clear the current recorded workflow? This cannot be undone.')) {    AppState.scribeSteps = []; // Clear the steps array    // Clear the UI displays    document.getElementById('scribeResults').innerHTML = ''; // Clear main results    document.getElementById('scribeActionResults').innerHTML = ''; // Clear action results too    // Update display (will show placeholder) and update button states    displayScribeSteps();    showSuccess('Workflow steps cleared.');  }}// Exports the recorded workflow in the specified formatasync function exportScribe(format) {  if (!AppState.scribeSteps || AppState.scribeSteps.length === 0) return showError('No workflow steps to export.', 'warning');  const filenameBase = `spectrum-ai-scribe-workflow-${Date.now()}`;  try {    let content, mimeType, filename;    // Get title and summary for context, providing defaults    const title = document.querySelector('#scribeResults .workflow-header h3')?.textContent || `Recorded Workflow (${AppState.scribeSteps.length} Steps)`;    const summary = document.querySelector('#scribeResults .workflow-header p')?.textContent || `Exported on ${new Date().toLocaleString()}`;    if (format === 'txt') {      content = `${title}\n${summary}\n---\n\n`;      content += AppState.scribeSteps.map(s => `${s.number}. ${s.instruction}\n   (URL: ${s.url})`).join('\n\n');      mimeType = 'text/plain;charset=utf-8';      filename = `${filenameBase}.txt`;      downloadFile(content, filename, mimeType); // Use utility function    } else if (format === 'json') {      const dataToExport = {        title: title,        summary: summary,        exportedAt: new Date().toISOString(),        totalSteps: AppState.scribeSteps.length,        steps: AppState.scribeSteps.map(s => ({          number: s.number, instruction: s.instruction, action: s.action,          element: { // Include key element details for potential reconstruction or analysis              tagName: s.element.tagName,              id: s.element.id || null,              className: s.element.className || null,              text: s.element.text || null,              ariaLabel: s.element.ariaLabel || null,              placeholder: s.element.placeholder || null,              type: s.element.type || null,              name: s.element.name || null,              value: s.element.value || null, // Be mindful of sensitive data in values              href: s.element.href || null          },          timestamp: s.timestamp,          url: s.url          // Note: Screenshot data URL is intentionally omitted from JSON for size and potential privacy        })),      };      content = JSON.stringify(dataToExport, null, 2); // Pretty print JSON      mimeType = 'application/json;charset=utf-8';      filename = `${filenameBase}.json`;      downloadFile(content, filename, mimeType);    } else if (format === 'pdf') {      // Check if jsPDF library is loaded      if (typeof window.jspdf === 'undefined' || typeof window.jspdf.jsPDF === 'undefined') {        throw new Error("jsPDF library is not loaded. Cannot export as PDF. Ensure jspdf.umd.min.js is included.");      }      showStatus('scribeStatus', 'Generating PDF, please wait...', true);      // Use a timeout to allow UI update before blocking for PDF generation      await new Promise(resolve => setTimeout(resolve, 50));      await exportScribePDF(filenameBase); // Call dedicated PDF export function      showStatus('scribeStatus', '', false);      // Success message is handled within exportScribePDF      return; // Return early as download happens in exportScribePDF    } else {        throw new Error(`Unsupported export format requested: ${format}`);    }    showSuccess(`Workflow successfully exported as ${format.toUpperCase()}`);  } catch (error) {    console.error(`Export Scribe (${format}) error:`, error);    showError(`Export failed: ${error.message}`, 'error');    showStatus('scribeStatus', '', false); // Clear status if PDF export fails here  }}// Handles PDF generation using jsPDFasync function exportScribePDF(filenameBase) {  const { jsPDF } = window.jspdf;  const doc = new jsPDF({ orientation: 'p', unit: 'pt', format: 'a4' }); // Use points, standard A4  const margin = 40;  const pageHeight = doc.internal.pageSize.getHeight();  const pageWidth = doc.internal.pageSize.getWidth();  const usableWidth = pageWidth - 2 * margin;  let y = margin; // Current y position on the page  // --- Add Title and Summary ---  const title = document.querySelector('#scribeResults .workflow-header h3')?.textContent || 'Recorded Workflow';  const summary = document.querySelector('#scribeResults .workflow-header p')?.textContent || '';  doc.setFontSize(18);  doc.setFont(undefined, 'bold');  // Use splitTextToSize for potentially long titles  const titleLines = doc.splitTextToSize(title, usableWidth);  doc.text(titleLines, margin, y);  y += titleLines.length * (18 * 1.15) + 10; // Adjust spacing based on line height factor  if (summary) {    doc.setFontSize(10);    doc.setFont(undefined, 'normal');    const summaryLines = doc.splitTextToSize(summary, usableWidth);    doc.text(summaryLines, margin, y);    y += summaryLines.length * (10 * 1.15) + 15; // Space after summary  }  // --- End Title and Summary ---  // --- Add Steps ---  doc.setFontSize(10);  doc.setFont(undefined, 'normal');  for (const step of AppState.scribeSteps) {      // Check if new page is needed BEFORE adding content      const stepText = `${step.number}. ${step.instruction}`;      const textLines = doc.splitTextToSize(stepText, usableWidth);      const textHeight = textLines.length * (10 * 1.15); // Use line height factor      let spaceNeeded = textHeight + 10; // Base space + padding      // Check if screenshot exists and estimate its height      let imgHeight = 0;      let imgWidth = usableWidth * 0.8; // Make image slightly smaller than usable width       const imgX = margin + (usableWidth * 0.1); // Center the smaller image      if (step.screenshot) {          try {              const imgProps = doc.getImageProperties(step.screenshot);              imgHeight = (imgProps.height * imgWidth) / imgProps.width;              // Limit max image height to prevent huge images dominating page              imgHeight = Math.min(imgHeight, pageHeight / 3);              spaceNeeded += imgHeight + 10; // Add screenshot height + padding          } catch {              console.warn(`Could not get properties for screenshot ${step.number}, estimating space.`);              imgHeight = 0; // Reset height if properties fail              spaceNeeded += 20; // Add some space for potential error message or placeholder          }      }      // Add new page if current step doesn't fit      if (y + spaceNeeded > pageHeight - margin) {          doc.addPage();          y = margin; // Reset y position for new page      }      // Add step text (instruction)      doc.setFont(undefined, 'bold');      doc.text(stepText, margin, y, { maxWidth: usableWidth });      doc.setFont(undefined, 'normal');      y += textHeight + 5; // Move y down after text      // Add screenshot      if (step.screenshot && imgHeight > 0) {          try {              // Add a border around the image for clarity              doc.setDrawColor(200); // Light gray border              doc.rect(imgX - 1, y - 1, imgWidth + 2, imgHeight + 2);              // Add the image              doc.addImage(step.screenshot, 'JPEG', imgX, y, imgWidth, imgHeight);              y += imgHeight + 10; // Move y down after image + padding          } catch (imgError) {              console.warn(`Failed to add screenshot image for step ${step.number} to PDF:`, imgError);              doc.setFontSize(8).setTextColor(150, 0, 0); // Error color              doc.text(`[Could not embed screenshot: ${imgError.message.substring(0,50)}...]`, imgX, y);              doc.setTextColor(0); // Reset color              doc.setFontSize(10); // Reset font size              y += 15;          }      } else if (step.screenshot) { // If screenshot existed but failed properties earlier           doc.setFontSize(8).setTextColor(150); // Muted color           doc.text(`[Screenshot data invalid or missing]`, margin + 10, y);           doc.setTextColor(0); // Reset color           doc.setFontSize(10); // Reset font size           y += 15;      }       else {           y += 5; // Add smaller padding below text if there was no screenshot attempt      }  }  // --- End Steps ---  // --- Save PDF ---  try {      // Use blob output for potentially better performance/compatibility      const pdfBlob = doc.output('blob');      downloadFile(pdfBlob, `${filenameBase}.pdf`, 'application/pdf'); // Use utility      showSuccess('Workflow PDF generated successfully!');  } catch (saveError) {       console.error("Failed to generate or save PDF:", saveError);       showError(`Could not save PDF: ${saveError.message}`, 'error');  }  // --- End Save PDF ---}// Triggers a file download in the browser (Utility Function)function downloadFile(content, filename, mimeType) {  try {    const blob = (content instanceof Blob) ? content : new Blob([content], { type: mimeType });    const url = URL.createObjectURL(blob);    const a = document.createElement('a');    a.href = url;    a.download = filename;    document.body.appendChild(a); // Append link to body for Firefox compatibility    a.click(); // Simulate click to trigger download    // Cleanup    setTimeout(() => {       document.body.removeChild(a);       URL.revokeObjectURL(url); // Free up memory    }, 100);  } catch (e) {      console.error("File download failed:", e);      showError("Could not trigger file download.", "error");  }}// Make functions available globally if needed by other parts (e.g., message handler, commands)window.reinjectScribeContentScript = reinjectScribeContentScript;window.startScribeRecording = startScribeRecording; // Expose for context menu/commandwindow.handleClickCapture = handleClickCapture; // Called by central message handlerconsole.log('âœ… Scribe module definitions loaded');// ============================================// SPECTRUM AI PRO ENHANCED v3.1// History Module - Audit History Management// ============================================// ============================================// HISTORY MODULE// ============================================console.log('âœ… History module loaded');function initializeHistory() {  const searchInput = document.getElementById('historySearchInput');  const exportBtn = document.getElementById('exportHistoryButton');  const importBtn = document.getElementById('importHistoryButton');  const clearBtn = document.getElementById('clearHistoryButton');  searchInput?.addEventListener('input', (e) => filterHistory(e.target.value));  exportBtn?.addEventListener('click', exportHistory);  importBtn?.addEventListener('click', () => document.getElementById('importFileInput')?.click());  clearBtn?.addEventListener('click', clearAllHistory);  // File input for import  const fileInput = document.createElement('input');  fileInput.type = 'file';  fileInput.id = 'importFileInput';  fileInput.accept = '.json';  fileInput.style.display = 'none';  fileInput.addEventListener('change', handleHistoryImport);  document.body.appendChild(fileInput);  // Load history on initialization  loadHistory();}async function loadHistory() {  try {    const result = await chrome.storage.local.get('auditHistory');    const history = result.auditHistory || [];    displayHistory(history);  } catch (error) {    console.error('Load history error:', error);    showError('Failed to load history');  }}function displayHistory(history) {  const resultsDiv = document.getElementById('historyResults');  if (!resultsDiv) return;  if (history.length === 0) {    resultsDiv.innerHTML = '<p class="placeholder">No audit history yet. Run an audit to get started!</p>';    return;  }  resultsDiv.innerHTML = `    <div class="history-list">      ${history.map((item, index) => `        <div class="history-item" data-index="${index}" data-id="${item.id}">          <div class="history-header">            <div class="history-info">              <h4 class="history-url">${getHostname(item.url)}</h4>              <span class="history-date">${formatDate(item.date)}</span>            </div>            <div class="history-score ${getScoreClass(item.data?.overall || 0)}">              ${item.data?.overall || 'N/A'}            </div>          </div>          <div class="history-meta">            <span class="history-stat">              <span class="stat-label">Health:</span>              <span class="stat-value">${item.data?.health || 'N/A'}</span>            </span>            <span class="history-stat">              <span class="stat-label">Issues:</span>              <span class="stat-value">${(item.data?.errors || 0) + (item.data?.warnings || 0)}</span>            </span>          </div>          <div class="history-actions">            <button class="btn btn-sm view-history-btn" data-index="${index}">              ðŸ‘ï¸ View Report            </button>            <button class="btn btn-sm delete-history-btn" data-id="${item.id}">              ðŸ—‘ï¸ Delete            </button>          </div>        </div>      `).join('')}    </div>  `;  // Add event listeners  document.querySelectorAll('.view-history-btn').forEach(btn => {    btn.addEventListener('click', (e) => {      const index = parseInt(e.target.dataset.index);      loadHistoryReport(history[index]);    });  });  document.querySelectorAll('.delete-history-btn').forEach(btn => {    btn.addEventListener('click', async (e) => {      const id = parseInt(e.target.dataset.id);      await deleteHistoryItem(id);    });  });}async function filterHistory(searchTerm) {  try {    const result = await chrome.storage.local.get('auditHistory');    const history = result.auditHistory || [];    if (!searchTerm.trim()) {      displayHistory(history);      return;    }    const filtered = history.filter(item => {      const url = item.url.toLowerCase();      const hostname = getHostname(item.url).toLowerCase();      const search = searchTerm.toLowerCase();      return url.includes(search) || hostname.includes(search);    });    displayHistory(filtered);  } catch (error) {    console.error('Filter history error:', error);  }}async function loadHistoryReport(historyItem) {  try {    // Switch to auditor tab    const auditorTab = document.querySelector('.tab-link[data-tab="auditor"]');    if (auditorTab) {      auditorTab.click();    }    // Load data into AppState    AppState.auditData = historyItem.data;    AppState.auditReport = historyItem.report;    // Display the dashboard    displayAuditDashboard(historyItem.data);    // Show success message    showSuccess('Historical report loaded successfully!');  } catch (error) {    console.error('Load history report error:', error);    showError('Failed to load report');  }}async function deleteHistoryItem(itemId) {  if (!confirm('Are you sure you want to delete this audit report?')) {    return;  }  try {    const result = await chrome.storage.local.get('auditHistory');    const history = result.auditHistory || [];    const updatedHistory = history.filter(item => item.id !== itemId);    await chrome.storage.local.set({ auditHistory: updatedHistory });    // Reload display    displayHistory(updatedHistory);    showSuccess('Report deleted successfully');  } catch (error) {    console.error('Delete history error:', error);    showError('Failed to delete report');  }}async function clearAllHistory() {  if (!confirm('Are you sure you want to delete ALL audit history? This cannot be undone.')) {    return;  }  try {    await chrome.storage.local.set({ auditHistory: [] });    // Clear display    displayHistory([]);    showSuccess('All history cleared');  } catch (error) {    console.error('Clear history error:', error);    showError('Failed to clear history');  }}async function exportHistory() {  try {    const result = await chrome.storage.local.get('auditHistory');    const history = result.auditHistory || [];    if (history.length === 0) {      showError('No history to export');      return;    }    const exportData = {      version: '3.1',      exportDate: new Date().toISOString(),      totalReports: history.length,      reports: history    };    const json = JSON.stringify(exportData, null, 2);    const blob = new Blob([json], { type: 'application/json' });    const url = URL.createObjectURL(blob);    const a = document.createElement('a');    a.href = url;    a.download = `spectrum-ai-history-${Date.now()}.json`;    a.click();    URL.revokeObjectURL(url);    showSuccess(`Exported ${history.length} audit reports`);  } catch (error) {    console.error('Export history error:', error);    showError('Failed to export history');  }}async function handleHistoryImport(event) {  const file = event.target.files[0];  if (!file) return;  try {    const text = await file.text();    const importData = JSON.parse(text);    // Validate format    if (!importData.reports || !Array.isArray(importData.reports)) {      throw new Error('Invalid history file format');    }    // Get existing history    const result = await chrome.storage.local.get('auditHistory');    const existingHistory = result.auditHistory || [];    // Merge histories (avoid duplicates by ID)    const existingIds = new Set(existingHistory.map(item => item.id));    const newReports = importData.reports.filter(item => !existingIds.has(item.id));    const mergedHistory = [...existingHistory, ...newReports];    // Respect max history limit    const maxHistory = AppState.settings?.maxHistory || 100;    if (mergedHistory.length > maxHistory) {      mergedHistory.length = maxHistory;    }    // Save merged history    await chrome.storage.local.set({ auditHistory: mergedHistory });    // Reload display    displayHistory(mergedHistory);    showSuccess(`Imported ${newReports.length} new audit reports`);  } catch (error) {    console.error('Import history error:', error);    showError('Failed to import history: ' + error.message);  } finally {    // Reset file input    event.target.value = '';  }}// Helper functionsfunction getHostname(url) {  try {    const urlObj = new URL(url);    return urlObj.hostname.replace('www.', '');  } catch (error) {    return url;  }}function formatDate(dateString) {  try {    const date = new Date(dateString);    const now = new Date();    const diffMs = now - date;    const diffMins = Math.floor(diffMs / 60000);    const diffHours = Math.floor(diffMs / 3600000);    const diffDays = Math.floor(diffMs / 86400000);    if (diffMins < 60) {      return `${diffMins} minute${diffMins !== 1 ? 's' : ''} ago`;    } else if (diffHours < 24) {      return `${diffHours} hour${diffHours !== 1 ? 's' : ''} ago`;    } else if (diffDays < 7) {      return `${diffDays} day${diffDays !== 1 ? 's' : ''} ago`;    } else {      return date.toLocaleDateString();    }  } catch (error) {    return dateString;  }}function getScoreClass(score) {  if (score >= 80) return 'excellent';  if (score >= 60) return 'good';  if (score >= 40) return 'fair';  return 'poor';}/** * SPECTRUM AI PRO ENHANCED v3.2.1 * Chat Module - Context-Aware AI Assistant */console.log('ðŸ’¬ Chat module loading...');// Chat histories for each module (in-memory, reset on panel close/reload)const chatHistories = {  auditor: [],  organizer: [],  scribe: []};// **FIX: Define getWelcomeMessage BEFORE initializeChat calls initializeChatWelcome**/** * Get welcome message for a module * @param {string} module - Module name * @returns {string} Welcome message */function getWelcomeMessage(module) {  switch (module) {    case 'auditor':      return 'Run an audit using the "Run 12-Point Audit" button, then ask me anything about the results, scores, or recommendations!';    case 'organizer':      return 'Click "Analyze & Group Tabs" to get started, then ask me about the suggested groups or select one for actions.';    case 'scribe':      return 'Click "Start Recording" to capture a workflow, then ask me about the steps or potential improvements.';    default:      return 'Welcome! How can I assist you today?';  }}/** * Initialize chat interfaces for all modules */function initializeChat() {  ['auditor', 'organizer', 'scribe'].forEach(module => {    const input = document.getElementById(`${module}ChatInput`);    const sendBtn = document.getElementById(`${module}ChatSend`);    const clearBtn = document.getElementById(`${module}ChatClear`); // Assuming clear buttons exist with this ID pattern    const messagesContainer = document.getElementById(`${module}ChatMessages`); // Need this for welcome message    // Enter key listener    input?.addEventListener('keypress', (e) => {      if (e.key === 'Enter' && !e.shiftKey && !input.disabled) { // Send on Enter (not Shift+Enter), ignore if disabled        e.preventDefault(); // Prevent newline        sendChatMessage(module);      }    });    // Send button listener    sendBtn?.addEventListener('click', () => sendChatMessage(module));    // Clear button listener    clearBtn?.addEventListener('click', () => clearChatHistory(module));    // Initialize welcome message if container exists    if (messagesContainer) {        initializeChatWelcome(module); // Call welcome message setup    } else {         console.warn(`Messages container not found for ${module} chat.`);    }  });  console.log('Chat interfaces initialized.');}/** * Send chat message for a specific module * @param {string} module - Module name (auditor, organizer, scribe) */async function sendChatMessage(module) {  const inputId = `${module}ChatInput`;  const messagesId = `${module}ChatMessages`;  const input = document.getElementById(inputId);  const messagesContainer = document.getElementById(messagesId);  const sendButton = document.getElementById(`${module}ChatSend`);  if (!input || !messagesContainer || !sendButton) {      console.error(`Chat elements for module "${module}" not found.`);      return;  }  const userMessage = input.value.trim();  if (!userMessage) return; // Ignore empty messages  // --- Disable input during processing ---  input.value = ''; // Clear input immediately  input.disabled = true;  sendButton.disabled = true;  // ---  // Add user message to UI and history  addChatMessage(messagesContainer, userMessage, 'user');  chatHistories[module].push({ role: 'user', content: userMessage });  // Get context specific to the module  const context = getChatContext(module);  // If context is explicitly null (meaning prerequisites not met), show specific message  if (context === null) {    const noContextMsg = getNoContextMessage(module);    addChatMessage(messagesContainer, noContextMsg, 'assistant error'); // Use error style for this message    chatHistories[module].push({ role: 'assistant', content: noContextMsg });    // Re-enable input    input.disabled = false;    sendButton.disabled = false;    input.focus();    return;  }  // Show typing indicator  const typingIndicator = addChatMessage(messagesContainer, '...', 'assistant typing');  try {     // --- AI Check ---     if (!AppState.settings?.aiEnabled) {        throw new Error("AI features are currently disabled in settings.");     }     if (!aiManager) { // Should not happen if main.js is correct         throw new Error("AI Manager not initialized.");     }     // FIX: Attempt to create session; this handles availability checks & download triggers     await aiManager.createSession(); // Throws if unavailable after check/attempt     // --- End AI Check ---    // Create a container for the streaming AI response    const assistantMessageDiv = document.createElement('div');    assistantMessageDiv.className = 'chat-message assistant'; // Style as assistant message    const contentDiv = document.createElement('div');    contentDiv.className = 'message-content'; // Add class for potential styling    assistantMessageDiv.appendChild(contentDiv);    // Remove typing indicator *before* adding the new message container    typingIndicator.remove();    messagesContainer.appendChild(assistantMessageDiv);    messagesContainer.scrollTop = messagesContainer.scrollHeight; // Scroll down    // Stream the AI response    let fullResponse = '';    // Use the streamPrompt method which expects context as the second argument    await aiManager.streamPrompt(userMessage, context, (chunk) => {      fullResponse = chunk; // Update full response with latest chunk      // Render the markdown chunk into the content div using the 'marked' utility      contentDiv.innerHTML = marked.parse(chunk); // Assumes 'marked' is globally available from utils/core      // Keep scrolled to the bottom      messagesContainer.scrollTop = messagesContainer.scrollHeight;    }, {}); // Pass empty options object if needed    // Add final response to history    chatHistories[module].push({ role: 'assistant', content: fullResponse });  } catch (error) {    console.error(`Chat error in module ${module}:`, error);    // Ensure typing indicator is removed on error, check if it still exists    const stillTyping = messagesContainer.querySelector('.assistant.typing');    if (stillTyping) stillTyping.remove();    // Add error message to chat UI    addChatMessage(messagesContainer, `Sorry, I encountered an error: ${error.message}. Please check AI status or try again.`, 'assistant error');     // Optionally add error to history    // chatHistories[module].push({ role: 'assistant', content: `Error: ${error.message}` });  } finally {    // Re-enable input regardless of success or failure    input.disabled = false;    sendButton.disabled = false;    input.focus();  }}/** * Add a chat message to the container * @param {HTMLElement} messagesContainer - Container element * @param {string} content - Message content * @param {string} role - Message role (user, assistant, assistant typing, assistant error, assistant welcome) * @returns {HTMLElement} Created message element */function addChatMessage(messagesContainer, content, role) {  // Ensure messagesContainer exists  if (!messagesContainer) {      console.error("Cannot add chat message: messagesContainer is null or undefined.");      // Return a dummy element to prevent errors in caller      return document.createElement('div');  }  const messageDiv = document.createElement('div');  messageDiv.className = `chat-message ${role}`; // Role doubles as class  const contentDiv = document.createElement('div');  contentDiv.className = 'message-content';  if (role === 'assistant typing') {      // Specific HTML for typing indicator      contentDiv.innerHTML = '<div class="typing-indicator"><span></span><span></span><span></span></div>';  } else if (role === 'user') {      // Use textContent for user messages to prevent HTML injection      contentDiv.textContent = content;  } else {       // Use markdown parser for assistant messages (including welcome and errors)       // Check if 'marked' exists before using it       if (typeof marked !== 'undefined' && marked.parse) {         contentDiv.innerHTML = marked.parse(content);       } else {         console.warn("'marked' parser not found. Displaying raw content for assistant message.");         // Fallback to textContent if marked is missing         contentDiv.textContent = content;       }  }  messageDiv.appendChild(contentDiv);  messagesContainer.appendChild(messageDiv);  // Scroll to the bottom smoothly  messagesContainer.scrollTo({ top: messagesContainer.scrollHeight, behavior: 'smooth' });  return messageDiv; // Return the created element}/** * Get chat context for a module based on AppState * @param {string} module - Module name * @returns {string|null} Context string or null if prerequisite data is missing */function getChatContext(module) {  switch (module) {    case 'auditor': return getAuditorContext();    case 'organizer': return getOrganizerContext();    case 'scribe': return getScribeContext();    default:      console.warn(`Unknown module requested for chat context: ${module}`);      // Return a generic context if module is unknown but AI should still respond somehow      return "You are a helpful AI assistant integrated into a browser extension. The user is in an unknown section.";  }}// Context for the Auditor chatfunction getAuditorContext() {  // FIX: Return null if audit data/report is missing, indicating prerequisites not met  if (!AppState.auditData || !AppState.auditReport) return null;  // Construct context string with key audit data  return `Context: The user is viewing a website audit report.Overall Score: ${AppState.auditData.overallScore ?? 'N/A'}/100Health Status: ${AppState.auditData.health ?? 'N/A'}Identified Issues: ${AppState.auditData.issues?.errors ?? 0} errors, ${AppState.auditData.issues?.warnings ?? 0} warnings.Category Scores (0-10): ${Object.entries(AppState.auditData.scores ?? {}).map(([k, v]) => `${k}: ${v?.toFixed(1) ?? 'N/A'}`).join(', ')}Report Summary (first 1000 characters):${AppState.auditReport.substring(0, 1000)}...Task: Answer the user's questions based *only* on the provided audit context above. Be specific and refer to the scores or report details when relevant. Do not ask for the full report unless necessary to answer.`;}// Context for the Organizer chatfunction getOrganizerContext() {  // FIX: Return null if groups are missing  if (!AppState.organizerGroups || AppState.organizerGroups.length === 0) return null;  // Build context string with group info  let context = `Context: The user's browser tabs have been analyzed and grouped.Total Groups Suggested: ${AppState.organizerGroups.length}Groups Summary:`;  AppState.organizerGroups.forEach((group, index) => {    // Add safety check for group.tabs    const tabTitles = group.tabs ? group.tabs.map(t => t.title?.substring(0, 50) || 'Untitled').join('; ') : 'No tab details';    context += `Group ${index + 1}: "${group.name}" (${group.tabIds?.length || 0} tabs, ${group.confidence}% confidence)Tab Titles: ${tabTitles}`;  });  // Add info about the currently selected group, if any  if (AppState.selectedGroup !== null && AppState.organizerGroups[AppState.selectedGroup]) {    const selected = AppState.organizerGroups[AppState.selectedGroup];    context += `CURRENTLY SELECTED GROUP FOR ACTIONS: "${selected.name}" (${selected.tabIds?.length || 0} tabs)`;  }  context += `Task: Answer questions about these tab groups, the selected group (if any), or suggest organization actions based *only* on the provided group context.`;  return context;}// Context for the Scribe chatfunction getScribeContext() {  // FIX: Return null if steps are missing  if (!AppState.scribeSteps || AppState.scribeSteps.length === 0) return null;  const title = document.querySelector('#scribeResults .workflow-header h3')?.textContent || 'Recorded Workflow';  // Build context with workflow title and steps  return `Context: A user workflow titled "${title}" has been recorded.Total Steps Recorded: ${AppState.scribeSteps.length}Recorded Steps:${AppState.scribeSteps.map(s => `${s.number}. ${escapeHtml(s.instruction)}`).join('\n')}Task: Answer the user's questions about this specific workflow based *only* on the steps provided. Explain steps, discuss potential issues, or clarify the process shown.`;}/** * Get message when no context is available for a module * @param {string} module - Module name * @returns {string} No context message */function getNoContextMessage(module) {  switch (module) {    case 'auditor':      return 'I need an audit report to answer questions. Please click "ðŸš€ Run 12-Point Audit" first.';    case 'organizer':      return 'I need analyzed tabs to help. Please click "ðŸ“‚ Analyze & Group Tabs" first.';    case 'scribe':      return 'I need a recorded workflow to discuss. Please click "ðŸŽ¬ Start Recording" first.';    default:      return 'No context is available for this section yet. Please perform the main action for this tab first.';  }}/** * Clear chat history for a module * @param {string} module - Module name */function clearChatHistory(module) {  // Check if history exists for the module and has entries  if (!chatHistories[module] || chatHistories[module].length === 0) {      if (typeof showError === 'function') showError(`Chat history for ${module} is already empty.`, "info");      return;  }  if (confirm(`Are you sure you want to clear the chat history for the ${module} tab?`)) {    chatHistories[module] = []; // Reset the history array for the specific module    const messagesId = `${module}ChatMessages`;    const messagesContainer = document.getElementById(messagesId);    if (messagesContainer) {      messagesContainer.innerHTML = ''; // Clear the UI      initializeChatWelcome(module); // Add back the welcome message    } else {        console.warn(`Messages container not found for clearing chat: ${messagesId}`);    }    if (typeof showSuccess === 'function') {      showSuccess(`Chat history for ${module} cleared.`);    }  }}/** * Initialize welcome messages for all chat modules * @param {string} [specificModule=null] - Optional: Initialize only a specific module */function initializeChatWelcome(specificModule = null) {  const modules = specificModule ? [specificModule] : ['auditor', 'organizer', 'scribe'];  modules.forEach(module => {    const messagesId = `${module}ChatMessages`;    const messagesContainer = document.getElementById(messagesId);    // Add welcome message only if the container exists and is currently empty    if (messagesContainer && messagesContainer.children.length === 0) {        // Use addChatMessage for consistent formatting and handling (e.g., markdown)        addChatMessage(messagesContainer, getWelcomeMessage(module), 'assistant welcome'); // Added 'welcome' class for potential styling    }  });}// Export functions if needed globally (though typically called internally or via main.js)window.initializeChat = initializeChat;window.sendChatMessage = sendChatMessage;window.clearChatHistory = clearChatHistory;// getWelcomeMessage and initializeChatWelcome are now defined correctly before use.console.log('âœ… Chat module loaded');// ============================================// MODAL MODULE// ============================================function initializeModal() {  document.getElementById('settingsBtn')?.addEventListener('click', openSettings);  document.getElementById('modalCloseBtn')?.addEventListener('click', closeModal);  document.getElementById('cancelSettingsButton')?.addEventListener('click', closeModal);  document.getElementById('saveSettingsButton')?.addEventListener('click', saveSettingsFromModal);}function openSettings() {  const modal = document.getElementById('modal');  const content = document.getElementById('modalContent');  content.innerHTML = `    <div class="settings-form">      <h3>ðŸ¤– AI Configuration</h3>      <label><input type="checkbox" id="aiEnabled" ${AppState.setting